BEGIN;
CREATE TABLE public.tac_academy_courses (
  slug text PRIMARY KEY,
  title text NOT NULL,
  lessons jsonb NOT NULL,
  questions jsonb NOT NULL,
  answer_key text NOT NULL,
  CHECK (length(answer_key) = jsonb_array_length(questions))
);
CREATE TABLE public.tac_academy_progress (
  advisor_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  course text NOT NULL REFERENCES public.tac_academy_courses(slug),
  completed text[] NOT NULL DEFAULT '{}',
  last_lesson text,
  best_correct integer,
  last_correct integer,
  attempts integer NOT NULL DEFAULT 0,
  PRIMARY KEY (advisor_id, course)
);
ALTER TABLE public.tac_academy_courses ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.tac_academy_progress ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.tac_academy_courses, public.tac_academy_progress FROM PUBLIC, anon, authenticated;

CREATE FUNCTION public.tac_academy_course(
  p_course text, p_lesson text DEFAULT NULL, p_complete boolean DEFAULT false,
  p_answers text[] DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  actor uuid := auth.uid();
  course_row public.tac_academy_courses%ROWTYPE;
  progress public.tac_academy_progress%ROWTYPE;
  result integer;
BEGIN
  IF actor IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = actor AND is_active AND deleted_at IS NULL AND role IN ('owner', 'advisor')
  ) THEN
    RAISE EXCEPTION 'Academy access denied' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO STRICT course_row FROM public.tac_academy_courses WHERE slug = p_course;
  IF p_lesson IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM jsonb_array_elements(course_row.lessons) AS lesson WHERE lesson->>'id' = p_lesson
  ) THEN
    RAISE EXCEPTION 'Unknown lesson' USING ERRCODE = '22023';
  END IF;
  IF p_answers IS NOT NULL THEN
    IF cardinality(p_answers) <> length(course_row.answer_key) OR EXISTS (
      SELECT 1 FROM unnest(p_answers) AS answer WHERE answer IS NULL OR answer !~ '^[A-D]$'
    ) THEN
      RAISE EXCEPTION 'Answer every exam question' USING ERRCODE = '22023';
    END IF;
    SELECT count(*) INTO result FROM unnest(p_answers) WITH ORDINALITY AS a(answer, n)
      WHERE answer = substr(course_row.answer_key, n::integer, 1);
  END IF;

  IF p_lesson IS NOT NULL OR result IS NOT NULL THEN
    INSERT INTO public.tac_academy_progress AS current_progress
      (advisor_id, course, last_lesson, completed, last_correct, best_correct, attempts)
    VALUES (actor, p_course, p_lesson,
      CASE WHEN p_complete AND p_lesson IS NOT NULL THEN ARRAY[p_lesson] ELSE ARRAY[]::text[] END,
      result, result, CASE WHEN result IS NULL THEN 0 ELSE 1 END)
    ON CONFLICT (advisor_id, course) DO UPDATE SET
      last_lesson = coalesce(EXCLUDED.last_lesson, current_progress.last_lesson),
      completed = CASE WHEN p_complete AND p_lesson IS NOT NULL AND NOT p_lesson = ANY(current_progress.completed)
        THEN array_append(current_progress.completed, p_lesson) ELSE current_progress.completed END,
      last_correct = coalesce(result, current_progress.last_correct),
      best_correct = greatest(result, current_progress.best_correct),
      attempts = current_progress.attempts + EXCLUDED.attempts;
  END IF;
  SELECT * INTO progress FROM public.tac_academy_progress WHERE advisor_id = actor AND course = p_course;

  RETURN jsonb_build_object(
    'title', course_row.title, 'lessons', course_row.lessons, 'questions', course_row.questions,
    'lastLesson', progress.last_lesson, 'completed', coalesce(progress.completed, ARRAY[]::text[]),
    'lastCorrect', progress.last_correct, 'bestCorrect', progress.best_correct,
    'attempts', coalesce(progress.attempts, 0)
  );
END;
$$;
REVOKE ALL ON FUNCTION public.tac_academy_course(text, text, boolean, text[]) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.tac_academy_course(text, text, boolean, text[]) TO authenticated;
INSERT INTO public.tac_academy_courses (slug,title,lessons,questions,answer_key) VALUES
('texas-pc','Texas General Lines P&C','[{"id": "start", "title": "Start here if you’re new to insurance", "html": "<h2>Start here if you’re new to insurance</h2><p>Property insurance helps pay for covered damage to things you own or insure. Liability insurance helps when someone claims you caused covered harm. Imagine a kitchen fire damages your own cabinets and spreads to a neighbor’s home. The cabinets lead to a property claim. The neighbor’s demand leads to a liability question.</p><p>For every scenario, ask who suffered the loss, what caused it, which coverage could respond, and what limit, exclusion or deductible applies. First try the question with notes closed. Then reveal the answer and explain why the other choices fail.</p><p><a href=\"#week-one\">Choose the 1-week path</a> · <a href=\"#week-two\">Choose the 2-week path</a> · <a href=\"#blueprint\">Open the study map</a></p>"}, {"id": "videos", "title": "Watch the videos", "html": "<h2>Watch the videos</h2><p>These three assignments link directly to the relevant segments on the Texas Department of Insurance YouTube channel. Open them in your browser while connected to the internet.</p><ol><li><a href=\"https://www.youtube.com/watch?v=YPEbsfMGudM&t=145s\">How to get licensed · start at 2:25</a>. Write the exam, fingerprint and application steps in order.</li><li><a href=\"https://www.youtube.com/watch?v=vKXHlQilwxs&t=709s\">Flood insurance for renters · start at 11:49</a>. Explain who insures the building and who insures the tenant’s belongings.</li><li><a href=\"https://www.youtube.com/watch?v=YPEbsfMGudM&t=474s\">Maintaining your Texas license · start at 7:54</a>. Find the renewal cycle and ethics requirement.</li></ol>"}, {"id": "week-one", "title": "1-week learning path", "html": "<h2>1-week learning path</h2><p>Block about 2–3 hours daily. Use this option if you can protect that time and leave room to repeat weak topics.</p><ol><li>Foundations. Read lessons 1–4 starting with <a href=\"#m1\">Lesson 1</a> and outline lessons 2–3 starting with <a href=\"#outline-2\">Outline lesson 2</a>. Calculate ACV and coinsurance without notes.</li><li>Home and specialty property. Read lessons 5–7 starting with <a href=\"#m5\">Lesson 5</a> and <a href=\"#outline-1\">Outline lesson 1</a>. Watch the flood clip and label homeowners coverages A–F from memory.</li><li>Personal auto and liability. Read lessons 8–10 starting with <a href=\"#m8\">Lesson 8</a>. Solve a split-limit claim and identify all four elements of negligence.</li><li>Business coverage. Read lessons 11–15 starting with <a href=\"#m11\">Lesson 11</a> and outline lessons 4–5 starting with <a href=\"#outline-4\">Outline lesson 4</a>. Explain which policy covers a damaged building, a customer injury and an employee injury.</li><li>Claims and Texas law. Read lessons 16–19 starting with <a href=\"#m16\">Lesson 16</a> and outline lessons 6–8 starting with <a href=\"#outline-6\">Outline lesson 6</a>. Watch the licensing and renewal clips. Rebuild the claim timeline from memory.</li><li>Mixed review. Take the <a href=\"#final\">16-question drill</a> with your notes closed. Review every miss and every guess. Make a short list of the rules you still confuse.</li><li>Exam rehearsal. Use the <a href=\"#ready\">readiness check</a> and take a fresh full-length timed mock.</li></ol>"}, {"id": "week-two", "title": "2-week learning path", "html": "<h2>2-week learning path</h2><p>Start here if you’re brand new. Plan about 60–90 minutes a day and allow a longer block for your full-length mock. Start each day by recalling yesterday’s rules.</p><ol><li>Get oriented. Watch the licensing clip and read <a href=\"#m1\">Lesson 1</a>. Explain risk, peril and hazard with one example.</li><li>Read <a href=\"#m2\">Lesson 2</a> and <a href=\"#outline-3\">Outline lesson 3</a>. Locate the promise, exclusion and duty in a sample policy question.</li><li>Read lessons 3–4 starting with <a href=\"#m3\">Lesson 3</a> and <a href=\"#outline-2\">Outline lesson 2</a>. Work both calculations without looking.</li><li>Read lessons 5–6 starting with <a href=\"#m5\">Lesson 5</a>. Draw a house, shed and contents and label the coverages.</li><li>Read <a href=\"#m7\">Lesson 7</a> and <a href=\"#outline-1\">Outline lesson 1</a>. Watch the flood clip and explain building versus contents coverage.</li><li>Read lessons 8–9 starting with <a href=\"#m8\">Lesson 8</a>. Apply split limits and explain PIP versus UM/UIM.</li><li>Read <a href=\"#m10\">Lesson 10</a> and review days 1–6. Tell a slip-and-fall story using duty, breach, causation and damages.</li><li>Read lessons 11–12 starting with <a href=\"#m11\">Lesson 11</a>. Distinguish property loss, interrupted income and third-party liability.</li><li>Read lessons 13–14 starting with <a href=\"#m13\">Lesson 13</a> and revisit the auto and workers’ comp portions of <a href=\"#outline-4\">Outline lesson 4</a>. Explain symbols 7–9.</li><li>Read <a href=\"#m15\">Lesson 15</a>, finish <a href=\"#outline-4\">Outline lesson 4</a> and read <a href=\"#outline-5\">Outline lesson 5</a>. Match each crime and professional exposure to the right coverage.</li><li>Read <a href=\"#m16\">Lesson 16</a> and <a href=\"#outline-6\">Outline lesson 6</a>. Walk through notice, proof of loss and settlement.</li><li>Read lessons 17–19 starting with <a href=\"#m17\">Lesson 17</a> and outline lessons 7–8 starting with <a href=\"#outline-7\">Outline lesson 7</a>. Watch the renewal clip and recall the Texas rules aloud.</li><li>Take the <a href=\"#final\">16-question drill</a> under time. Review misses and guesses using the study map.</li><li>Use the <a href=\"#ready\">readiness check</a> and take a fresh full-length timed mock.</li></ol>"}, {"id": "m1", "title": "Risk, peril and hazard", "html": "<small>LESSON 1 / 19</small><h2>Risk, peril and hazard</h2><p>A bakery has frayed wiring. A spark starts a fire and burns the oven. The possibility of loss is the risk. The wiring increased the chance of fire, so it is a physical hazard. Fire is the peril that caused the damage. The burned oven is a direct loss. Lost sales during repairs are an indirect loss. Pooling many similar exposures helps an insurer predict group losses even when it cannot predict which bakery will burn.</p><details><summary>Recall the rule, then reveal the memory cue</summary><blockquote>Peril does it. Hazard helps it happen.</blockquote></details><h3>Try it</h3><p><strong>An owner invents a loss. Which hazard?</strong></p><ol type=\"A\"><li>Morale hazard</li><li>Physical hazard</li><li>Speculative risk</li><li>Moral hazard</li></ol><details><summary>Check answer</summary><p><b>D. Moral hazard.</b> Moral involves dishonesty. Morale means carelessness, such as leaving the shop unlocked because it is insured.</p></details><p><small>Read further · <a href=\"https://www.pearsonvue.com/content/dam/VUE/vue/en/documents/publications/124401.pdf\">Pearson VUE · Texas exam outline, effective September 1, 2026</a></small></p>"}, {"id": "m2", "title": "Reading a contract", "html": "<small>LESSON 2 / 19</small><h2>Reading a contract</h2><p>Start with the declarations for names, dates, limits and locations. Read the insuring agreement for the promise, exclusions for what it takes away and conditions for duties. An endorsement can change any of these. A binder supplies temporary coverage. A certificate summarizes existing insurance. A valid contract requires agreement, consideration, capable parties and a legal purpose.</p><details><summary>Recall the rule, then reveal the memory cue</summary><blockquote>Binder binds. Certificate describes. Endorsement edits.</blockquote></details><h3>Try it</h3><p><strong>A landlord asks for additional insured status. Which document can actually amend the tenant’s policy?</strong></p><ol type=\"A\"><li>Endorsement</li><li>Certificate alone</li><li>Premium receipt</li><li>Proof of loss</li></ol><details><summary>Check answer</summary><p><b>A. Endorsement.</b> A certificate can report status that already exists. The policy terms or an endorsement grant it.</p></details><p><small>Read further · <a href=\"https://www.pearsonvue.com/content/dam/VUE/vue/en/documents/publications/124401.pdf\">Pearson VUE · Texas exam outline, effective September 1, 2026</a></small></p>"}, {"id": "m3", "title": "Valuing a property loss", "html": "<small>LESSON 3 / 19</small><h2>Valuing a property loss</h2><p>Replacement cost estimates what a comparable new item costs. In a standard exam calculation, actual cash value subtracts depreciation. Market value reflects a sale price and can include land. Insurable interest asks what financial loss the claimant would suffer. A mortgage lender and homeowner can both have an interest in one building. Indemnity aims to restore the financial position before the loss.</p><details><summary>Recall the rule, then reveal the memory cue</summary><blockquote>New less use gives a starting ACV.</blockquote></details><h3>Try it</h3><p><strong>A covered machine costs $12,000 new. Depreciation is $3,500 and the deductible is $1,000. What is the ACV settlement assuming sufficient limits?</strong></p><ol type=\"A\"><li>$12,000</li><li>$7,500</li><li>$8,500</li><li>$11,000</li></ol><details><summary>Check answer</summary><p><b>B. $7,500.</b> ACV is $8,500. The question asks for the settlement, so subtract the deductible once more to reach $7,500.</p></details><p><small>Read further · <a href=\"https://www.pearsonvue.com/content/dam/VUE/vue/en/documents/publications/124401.pdf\">Pearson VUE · Texas exam outline, effective September 1, 2026</a></small></p>"}, {"id": "m4", "title": "Coinsurance and limits", "html": "<small>LESSON 4 / 19</small><h2>Coinsurance and limits</h2><p>A commercial building worth $500,000 with an 80% coinsurance clause requires $400,000 of insurance to avoid a penalty. Carrying $300,000 meets three quarters of the requirement. For a $40,000 covered partial loss, the simplified payment before deductible is $30,000. Then apply the deductible and applicable limit. A blanket limit can span multiple items or locations. A specific limit applies to a designated item.</p><details><summary>Recall the rule, then reveal the memory cue</summary><blockquote>Did carry ÷ should carry × loss.</blockquote></details><h3>Try it</h3><p><strong>Using this example and a $2,000 deductible, what is the payment?</strong></p><ol type=\"A\"><li>$38,000</li><li>$22,000</li><li>$28,000</li><li>$30,000</li></ol><details><summary>Check answer</summary><p><b>C. $28,000.</b> The insurer pays 75% of $40,000, then subtracts $2,000. The 80% sets required insurance. It is not the payment percentage.</p></details><p><small>Read further · <a href=\"https://www.pearsonvue.com/content/dam/VUE/vue/en/documents/publications/124401.pdf\">Pearson VUE · Texas exam outline, effective September 1, 2026</a></small></p>"}, {"id": "m5", "title": "A walk through a homeowners policy", "html": "<small>LESSON 5 / 19</small><h2>A walk through a homeowners policy</h2><p>Picture a house, detached shed, moving boxes and hotel receipt. Under common homeowners forms A covers the dwelling, B other structures, C personal property and D loss of use. E addresses personal liability. F covers eligible medical payments to others. Attached features generally go with the dwelling. Additional living expense measures the necessary increase in living cost after a covered loss.</p><details><summary>Recall the rule, then reveal the memory cue</summary><blockquote>A attached, B backyard building, C contents, D displaced, E sued, F first aid.</blockquote></details><h3>Try it</h3><p><strong>A covered fire displaces a family. Their normal food bill is $180 and necessary meals now cost $310. What food expense enters the loss-of-use calculation?</strong></p><ol type=\"A\"><li>$180</li><li>$310</li><li>$490</li><li>$130</li></ol><details><summary>Check answer</summary><p><b>D. $130.</b> The increase is $310 minus $180. Other eligible extra expenses can be considered separately.</p></details><p><small>Read further · <a href=\"https://www.tdi.texas.gov/pubs/consumer/cb025.html\">TDI · home insurance guide</a></small></p>"}, {"id": "m6", "title": "Homeowners and dwelling forms", "html": "<small>LESSON 6 / 19</small><h2>Homeowners and dwelling forms</h2><p>HO-2 uses named perils. HO-3 generally covers the dwelling on an open-perils basis and contents for named perils. HO-5 generally broadens both. HO-4 serves tenants, HO-6 condo unit owners, and HO-8 can suit older homes using modified settlement terms. DP-1 is basic, DP-2 broad named perils, DP-3 generally open perils on buildings and named perils on contents. Dwelling forms commonly need liability added. On a DP form D is fair rental value and E, where provided, is additional living expense.</p><details><summary>Recall the rule, then reveal the memory cue</summary><blockquote>Four rents the floor. Six owns the unit. Always name the form before the letter.</blockquote></details><h3>Try it</h3><p><strong>A landlord loses rent after a covered fire at a rented dwelling. Which DP coverage fits?</strong></p><ol type=\"A\"><li>D, fair rental value</li><li>C, personal property</li><li>E, personal liability</li><li>B, other structures</li></ol><details><summary>Check answer</summary><p><b>A. D, fair rental value.</b> Lost rent belongs to the owner. On a homeowners form the same letter D has the broader label loss of use.</p></details><p><small>Read further · <a href=\"https://www.tdi.texas.gov/pubs/consumer/cb025.html\">TDI · home insurance guide</a></small></p>"}, {"id": "m7", "title": "Water, wind and property that travels", "html": "<small>LESSON 7 / 19</small><h2>Water, wind and property that travels</h2><p>Ask where water came from. A sudden pipe discharge inside a house and rising surface water entering from the street are different causes. Standard homeowners coverage generally excludes flood. A separate flood policy can cover a building, contents or both as purchased. Earth movement commonly needs separate coverage too. For a valuable ring, look at a scheduled personal articles floater and compare causes of loss and limits.</p><details><summary>Recall the rule, then reveal the memory cue</summary><blockquote>Trace the water. Follow the ring.</blockquote></details><aside><b>Watch with TDI</b> · <a href=\"https://www.youtube.com/watch?v=vKXHlQilwxs&t=709s\">How do you know if you need flood insurance? · renters segment at 11:49 ▶</a><p>After watching, explain to a tenant which belongings they would insure and what the landlord’s policy addresses.</p></aside><h3>Try it</h3><p><strong>A tenant loses furniture when a creek overflows. Which coverage should the tenant have considered?</strong></p><ol type=\"A\"><li>Personal umbrella</li><li>Flood contents coverage</li><li>Landlord’s flood building coverage</li><li>Homeowners loss of use alone</li></ol><details><summary>Check answer</summary><p><b>B. Flood contents coverage.</b> The tenant owns the furniture. Building and contents are distinct interests even when damaged by the same water.</p></details><p><small>Read further · <a href=\"https://www.tdi.texas.gov/pubs/consumer/cb025.html\">TDI · home insurance guide</a></small></p>"}, {"id": "m8", "title": "Personal auto and Texas split limits", "html": "<small>LESSON 8 / 19</small><h2>Personal auto and Texas split limits</h2><p>Liability pays covered injury or damage owed to others. Collision handles impact with an object or overturn of the insured car. Other-than-collision includes hail, theft and contact with an animal. Texas minimum liability limits are $30,000 bodily injury per person, $60,000 bodily injury per accident and $25,000 property damage per accident. Apply the person limit first. A combined single limit uses one shared amount instead.</p><details><summary>Recall the rule, then reveal the memory cue</summary><blockquote>One person, all people, their property.</blockquote></details><h3>Try it</h3><p><strong>Two injured people have covered claims of $40,000 and $20,000. With 30/60/25 and no other claims, how much bodily injury liability is available for these claims?</strong></p><ol type=\"A\"><li>$40,000</li><li>$25,000</li><li>$50,000</li><li>$60,000</li></ol><details><summary>Check answer</summary><p><b>C. $50,000.</b> Cap the first at $30,000 and allow $20,000 for the second. The accident ceiling does not erase the individual cap.</p></details><p><small>Read further · <a href=\"https://www.tdi.texas.gov/pubs/consumer/cb020.html\">TDI · auto insurance guide</a></small></p>"}, {"id": "m9", "title": "PIP and uninsured drivers", "html": "<small>LESSON 9 / 19</small><h2>PIP and uninsured drivers</h2><p>PIP can pay covered medical expenses and certain lost income regardless of fault. Medical payments coverage focuses on eligible medical or funeral expenses. UM/UIM protects insured people against covered losses caused by drivers who lack sufficient liability insurance. In Texas, rejection of PIP or UM/UIM must be in writing. For a rideshare question, establish whether the app was off, waiting for a match or on an accepted trip before identifying the applicable coverage.</p><details><summary>Recall the rule, then reveal the memory cue</summary><blockquote>PIP follows the injured person. UM asks who hit them.</blockquote></details><h3>Try it</h3><p><strong>An injured passenger asks which first-party coverage can address lost wages as well as medical bills. Which answer fits?</strong></p><ol type=\"A\"><li>Medical payments</li><li>Collision</li><li>Property damage liability</li><li>PIP</li></ol><details><summary>Check answer</summary><p><b>D. PIP.</b> The lost-income clue separates PIP from medical payments. Check who qualifies and the applicable benefit limits.</p></details><p><small>Read further · <a href=\"https://www.tdi.texas.gov/pubs/consumer/cb020.html\">TDI · auto insurance guide</a></small></p>"}, {"id": "m10", "title": "Negligence and damages", "html": "<small>LESSON 10 / 19</small><h2>Negligence and damages</h2><p>A store owes shoppers reasonable care. Staff see a spill and ignore it. A shopper slips on it and breaks a wrist. Identify duty, breach, causation and damages in order. Bills and lost earnings are special damages. Pain and suffering are general damages. Punitive damages aim to punish. Vicarious liability can make an employer responsible for an employee acting within the scope of work.</p><details><summary>Recall the rule, then reveal the memory cue</summary><blockquote>Duty broken causes damage.</blockquote></details><h3>Try it</h3><p><strong>An unrelated injury happened before the shopper reached the spill. Which link is missing for that injury?</strong></p><ol type=\"A\"><li>Causation</li><li>Duty to customers</li><li>Existence of injury</li><li>Existence of a spill</li></ol><details><summary>Check answer</summary><p><b>A. Causation.</b> A dangerous condition and an injury can coexist. The claimant still needs a causal connection.</p></details><p><small>Read further · <a href=\"https://www.pearsonvue.com/content/dam/VUE/vue/en/documents/publications/124401.pdf\">Pearson VUE · Texas exam outline, effective September 1, 2026</a></small></p>"}, {"id": "m11", "title": "Commercial property and lost income", "html": "<small>LESSON 11 / 19</small><h2>Commercial property and lost income</h2><p>Separate the building, business personal property and property of others. Select a causes-of-loss form. Basic and broad list covered causes. Special generally starts with direct physical loss subject to exclusions. Business income addresses lost net income and continuing normal operating expenses during a covered suspension. Extra expense addresses eligible costs to keep operating. Inland marine can cover contractors’ mobile equipment. Equipment breakdown addresses defined breakdown events.</p><details><summary>Recall the rule, then reveal the memory cue</summary><blockquote>Walls, stock, stopped sales, restart costs.</blockquote></details><h3>Try it</h3><p><strong>A bakery rents a temporary oven after a covered fire to keep filling orders. Which coverage most directly addresses that rental?</strong></p><ol type=\"A\"><li>Employee theft</li><li>Extra expense</li><li>Building coverage</li><li>General liability</li></ol><details><summary>Check answer</summary><p><b>B. Extra expense.</b> The rental is an added operating cost. The damaged oven and lost income are separate parts of the claim.</p></details><p><small>Read further · <a href=\"https://www.pearsonvue.com/content/dam/VUE/vue/en/documents/publications/124401.pdf\">Pearson VUE · Texas exam outline, effective September 1, 2026</a></small></p>"}, {"id": "m12", "title": "CGL, packages and umbrella", "html": "<small>LESSON 12 / 19</small><h2>CGL, packages and umbrella</h2><p>Commercial general liability Coverage A addresses bodily injury and property damage liability. B covers specified personal and advertising injury offenses, such as libel. C covers limited medical payments for eligible people without proving fault. Products-completed operations concerns harm after a product leaves the business or work is completed. A BOP packages property and liability for eligible businesses. A commercial package can combine selected coverage parts. Excess adds limits. An umbrella may cover certain additional exposures subject to its own terms and retention.</p><details><summary>Recall the rule, then reveal the memory cue</summary><blockquote>A accident, B bad words, C care. Then read the exceptions.</blockquote></details><h3>Try it</h3><p><strong>A customer claims a contractor’s finished railing came loose weeks after installation and caused injury. Which exposure fits?</strong></p><ol type=\"A\"><li>Employers liability</li><li>Business income</li><li>Completed operations</li><li>Premises medical payments only</li></ol><details><summary>Check answer</summary><p><b>C. Completed operations.</b> The work had already been completed. The question concerns injury to a third party, distinct from the cost of fixing defective work itself.</p></details><p><small>Read further · <a href=\"https://www.pearsonvue.com/content/dam/VUE/vue/en/documents/publications/124401.pdf\">Pearson VUE · Texas exam outline, effective September 1, 2026</a></small></p>"}, {"id": "m13", "title": "Business auto symbols", "html": "<small>LESSON 13 / 19</small><h2>Business auto symbols</h2><p>Find the symbol beside the specific coverage in the declarations. Symbol 1 means any auto, 2 owned autos only, 3 owned private passenger autos only, 4 owned autos other than private passenger, 5 owned autos subject to no-fault, 6 owned autos subject to compulsory UM, 7 specifically described autos, 8 hired autos and 9 nonowned autos. An employee’s car used on a business errand is commonly a nonowned exposure for the employer. Garagekeepers addresses customers’ vehicles in the insured’s care under the form terms.</p><details><summary>Recall the rule, then reveal the memory cue</summary><blockquote>Seven listed, eight rented, nine belongs to someone else.</blockquote></details><h3>Try it</h3><p><strong>A firm rents a van from a rental agency and sends an employee in her own sedan to collect it. Which symbols correspond to the van and sedan for the firm?</strong></p><ol type=\"A\"><li>9 and 8</li><li>7 and 2</li><li>2 and 7</li><li>8 and 9</li></ol><details><summary>Check answer</summary><p><b>D. 8 and 9.</b> The company hired the van. The employee owns her sedan. Check the symbols separately for liability and physical damage.</p></details><p><small>Read further · <a href=\"https://www.pearsonvue.com/content/dam/VUE/vue/en/documents/publications/124401.pdf\">Pearson VUE · Texas exam outline, effective September 1, 2026</a></small></p>"}, {"id": "m14", "title": "Workers’ compensation in Texas", "html": "<small>LESSON 14 / 19</small><h2>Workers’ compensation in Texas</h2><p>Part One pays statutory benefits for qualifying work-related injuries. Benefits can include medical, income, death and burial benefits. Part Two addresses covered employers liability suits. Payroll, job classification and experience can affect premium. Most Texas private employers may choose whether to subscribe. Exceptions include coverage requirements for employees on certain public construction projects. Nonsubscribers face duties and liability consequences. An employee label by itself does not decide status.</p><details><summary>Recall the rule, then reveal the memory cue</summary><blockquote>One pays statutory benefits. Two answers covered suits.</blockquote></details><h3>Try it</h3><p><strong>A covered employee needs surgery after a work injury. Which part ordinarily pays the statutory medical benefit?</strong></p><ol type=\"A\"><li>Part One</li><li>Part Two</li><li>CGL Coverage C</li><li>Commercial auto collision</li></ol><details><summary>Check answer</summary><p><b>A. Part One.</b> The injured worker seeks a statutory benefit. Employers liability addresses a different route to liability.</p></details><p><small>Read further · <a href=\"https://www.tdi.texas.gov/wc/employer/index.html\">TDI · workers’ compensation for employers</a></small></p>"}, {"id": "m15", "title": "Crime, bonds and professional mistakes", "html": "<small>LESSON 15 / 19</small><h2>Crime, bonds and professional mistakes</h2><p>Robbery involves taking by force or threat against a person. Burglary questions commonly describe unlawful entry with policy-defined evidence. Employee theft focuses on who took the property. A surety bond has three parties. The principal promises performance, the obligee receives the promise, and the surety backs it. E&O covers specified professional mistakes. D&O addresses management wrongful acts, EPLI employment allegations, and cyber coverage defined data or network losses.</p><details><summary>Recall the rule, then reveal the memory cue</summary><blockquote>Principal performs. Obligee is owed. Surety stands behind.</blockquote></details><h3>Try it</h3><p><strong>A contractor must obtain a performance bond for a city project. Who is the obligee?</strong></p><ol type=\"A\"><li>The contractor’s employee</li><li>The city</li><li>The contractor</li><li>The surety</li></ol><details><summary>Check answer</summary><p><b>B. The city.</b> The city receives the contractual promise. The contractor is the principal even though the contractor buys the bond.</p></details><p><small>Read further · <a href=\"https://www.pearsonvue.com/content/dam/VUE/vue/en/documents/publications/124401.pdf\">Pearson VUE · Texas exam outline, effective September 1, 2026</a></small></p>"}, {"id": "m16", "title": "Claims and policy triggers", "html": "<small>LESSON 16 / 19</small><h2>Claims and policy triggers</h2><p>After a loss, give prompt notice, protect property from further damage, document it and supply proof of loss as required. Appraisal generally resolves amount-of-loss disputes. Subrogation lets a paying insurer pursue a responsible third party. A standard mortgage clause can preserve a qualifying lender’s rights when the borrower’s claim fails, subject to the lender’s duties. Occurrence coverage generally looks to when injury or damage occurred. Claims-made coverage looks to when the claim was first made and also requires attention to reporting terms and retroactive dates.</p><details><summary>Recall the rule, then reveal the memory cue</summary><blockquote>Appraisal asks “how much?” Subrogation asks “who owes us back?”</blockquote></details><h3>Try it</h3><p><strong>A pipe installer caused a covered loss. The insurer paid the owner and seeks reimbursement from the installer. Which principle?</strong></p><ol type=\"A\"><li>Coinsurance</li><li>Salvage</li><li>Subrogation</li><li>Appraisal</li></ol><details><summary>Check answer</summary><p><b>C. Subrogation.</b> The insurer is pursuing the responsible party. Salvage concerns remaining damaged property.</p></details><p><small>Read further · <a href=\"https://www.pearsonvue.com/content/dam/VUE/vue/en/documents/publications/124401.pdf\">Pearson VUE · Texas exam outline, effective September 1, 2026</a></small></p>"}, {"id": "m17", "title": "Texas licensing and market conduct", "html": "<small>LESSON 17 / 19</small><h2>Texas licensing and market conduct</h2><p>The commissioner enforces insurance laws and can investigate records and impose authorized discipline. A certificate of authority concerns the insurer. An agent needs the appropriate license and appointment where required. Domestic, foreign and alien describe where the insurer was formed relative to Texas. Misrepresentation includes materially misstating coverage. Rebating involves prohibited inducements. Defamation involves false statements about an insurer. For referrals, distinguish a name-only introduction from discussing specific policy terms or tying unlicensed compensation to purchase. See Insurance Code §4005.053.</p><details><summary>Recall the rule, then reveal the memory cue</summary><blockquote>Company authority, agent license. Ask who did what and how they got paid.</blockquote></details><aside><b>Watch with TDI</b> · <a href=\"https://www.youtube.com/watch?v=YPEbsfMGudM&t=474s\">Maintaining a Texas license · start at 7:54 ▶</a><p>Write down the typical renewal cycle and CE requirement. Check your answer against TDI’s CE page: 24 hours per two-year period, including three ethics hours, unless exempt.</p></aside><h3>Try it</h3><p><strong>An agent tells a buyer a standard home policy covers creek flooding to close the sale. Which conduct most directly fits?</strong></p><ol type=\"A\"><li>Defamation</li><li>Subrogation</li><li>Appraisal</li><li>Misrepresentation</li></ol><details><summary>Check answer</summary><p><b>D. Misrepresentation.</b> The statement falsely describes the product being sold. Defamation would involve a damaging false statement about another insurer or its business.</p></details><p><small>Read further · <a href=\"https://www.tdi.texas.gov/agent/agcehome.html\">TDI · continuing education</a> · <a href=\"https://statutes.capitol.texas.gov/\">Texas Legislature · look up cited code and section</a></small></p>"}, {"id": "m18", "title": "Texas claims clocks and policy endings", "html": "<small>LESSON 18 / 19</small><h2>Texas claims clocks and policy endings</h2><p>For an ordinary eligible first-party claim under Insurance Code §§542.055–.057, anchor each clock to the event. Generally, notice starts 15 days to acknowledge, begin investigating and request needed items. Receipt of all required items starts 15 business days for the written acceptance or rejection decision. Notice of acceptance generally starts five business days to pay. Extensions and special rules can apply. Declination rejects a new application, cancellation ends an active term, and nonrenewal ends coverage at expiration. Texas’s valued-policy rule for a total fire loss of insured real property is a separate statutory issue under §862.053.</p><details><summary>Recall the rule, then reveal the memory cue</summary><blockquote>Notice → investigate. Complete file → decide. Acceptance → pay.</blockquote></details><h3>Try it</h3><p><strong>For the ordinary decision deadline, what starts the 15-business-day clock?</strong></p><ol type=\"A\"><li>Receipt of all required materials</li><li>Policy inception</li><li>First report of damage in every case</li><li>Renewal notice</li></ol><details><summary>Check answer</summary><p><b>A. Receipt of all required materials.</b> The decision clock uses a complete claim file. Distinguish it from the initial acknowledgment clock.</p></details><p><small>Read further · <a href=\"https://statutes.capitol.texas.gov/\">Texas Legislature · look up cited code and section</a></small></p>"}, {"id": "m19", "title": "Texas markets of last resort", "html": "<small>LESSON 19 / 19</small><h2>Texas markets of last resort</h2><p>Match the problem to the program. TAIPA addresses basic auto liability access for eligible applicants. Texas FAIR Plan addresses eligible residential property when ordinary coverage is unavailable. TWIA addresses eligible wind and hail exposure in designated coastal areas. The guaranty association handles eligible covered claims after a member insurer becomes insolvent, within statutory limits. Surplus lines serves qualifying risks through eligible nonadmitted insurers and licensed placement. The medical liability JUA concerns eligible medical professional liability.</p><details><summary>Recall the rule, then reveal the memory cue</summary><blockquote>Car → TAIPA. House → FAIR. Coastal wind → TWIA. Failed carrier → guaranty.</blockquote></details><h3>Try it</h3><p><strong>A coastal owner specifically needs wind and hail coverage for an eligible property. Where should the agent check?</strong></p><ol type=\"A\"><li>Guaranty association</li><li>TWIA</li><li>TAIPA</li><li>Medical liability JUA</li></ol><details><summary>Check answer</summary><p><b>B. TWIA.</b> The location and peril point to TWIA. A coastal address alone does not establish eligibility.</p></details><p><small>Read further · <a href=\"https://statutes.capitol.texas.gov/\">Texas Legislature · look up cited code and section</a></small></p>"}, {"id": "blueprint", "title": "Pearson VUE study map", "html": "<h2>Pearson VUE study map</h2><p>Use the core lessons and the corresponding exam-outline lesson together. The counts below are scored items assigned to each outline section. The exam also includes pretest items.</p><table style=\"width:100%;text-align:left\"><thead><tr><th>Section</th><th>Scored</th><th>Core lessons</th></tr></thead><tbody><tr><td><a href=\"#outline-1\">I. Property policies</a></td><td>22</td><td>5–7, 11–12</td></tr><tr><td><a href=\"#outline-2\">II. Property insurance concepts</a></td><td>15</td><td>1, 3–4, 10, 16, 18</td></tr><tr><td><a href=\"#outline-3\">III. Property policy terms and federal rules</a></td><td>13</td><td>2, 16</td></tr><tr><td><a href=\"#outline-4\">IV. Casualty policies and bonds</a></td><td>23</td><td>8–9, 11–16</td></tr><tr><td><a href=\"#outline-5\">V. Casualty insurance concepts</a></td><td>15</td><td>1–4, 10, 12–16</td></tr><tr><td><a href=\"#outline-6\">VI. Casualty policy provisions</a></td><td>12</td><td>2, 12, 16, 18</td></tr><tr><td><a href=\"#outline-7\">State I. Texas rules common to P&C</a></td><td>18</td><td>17–18</td></tr><tr><td><a href=\"#outline-8\">State II. Texas line-specific P&C rules</a></td><td>12</td><td>7–9, 14, 18–19</td></tr></tbody></table><p><a href=\"https://www.pearsonvue.com/content/dam/VUE/vue/en/documents/publications/124401.pdf\">Official Pearson VUE outline · pages S7–S10</a></p>"}, {"id": "outline-1", "title": "Property policies", "html": "<small>GENERAL KNOWLEDGE · 22 SCORED QUESTIONS IN THIS SECTION</small><h2>Property policies</h2><p><b>Read with core lessons 5–7, 11–12.</b></p><p>A builder insures a structure while it is under construction with builders risk. Check covered materials, where they are located and what ends coverage, such as acceptance or occupancy under the form. A contractors equipment floater follows tools or machinery between jobs. Equipment breakdown covers defined mechanical, electrical or pressure failures. First-party cyber coverage can pay the insured’s own eligible restoration, interruption and incident-response costs. Third-party cyber responds to covered claims against the insured.</p><p>Mobile-home policies account for manufactured housing and require attention to movement exclusions or transport endorsements. Watercraft policies can combine hull, liability and related coverages. Farmowners policies can combine dwelling, farm property, machinery and liability. Wind and hail may carry a separate deductible or require a separate policy. Earthquake coverage addresses earth movement subject to terms, often with a separate deductible.</p><p>The NFIP offers separate building and contents coverage in participating communities. Ask which was purchased. A renter can insure contents. The ordinary waiting period is 30 days, with exceptions such as certain loan-related purchases. Consult current FEMA rules for eligibility, limits and settlement restrictions.</p><details><summary>Reveal memory cue</summary><blockquote>Build it → builders risk. Move it → floater. Breakdown → equipment breakdown.</blockquote></details><h3>Apply the rule</h3><p>A storm damages lumber intended for a house under construction. Which coverage do you check first?</p><details><summary>Check answer</summary><p>Builders risk. Verify the location of the lumber, the covered cause and whether the policy was still in force.</p></details><p><a href=\"https://www.floodsmart.gov/\">FEMA · National Flood Insurance Program</a></p>"}, {"id": "outline-2", "title": "Property insurance concepts", "html": "<small>GENERAL KNOWLEDGE · 15 SCORED QUESTIONS IN THIS SECTION</small><h2>Property insurance concepts</h2><p><b>Read with core lessons 1, 3–4, 10, 16, 18.</b></p><p>Pure risk has a possibility of loss or no loss. Speculative risk has a potential gain as well, such as investing. Stated amount commonly sets a ceiling subject to the loss settlement language. Agreed value is fixed or accepted for a specified policy purpose. In commercial property an agreed value option can suspend coinsurance when its requirements are met. Salvage value is the remaining worth of damaged property.</p><p>Proximate cause connects the loss to an effective cause through a legally meaningful chain. Check exclusions when several causes contribute. Vacant generally means lacking occupants and enough property or activity for customary use. Unoccupied generally means nobody is there while it remains furnished. The policy can define these precisely and restrict some losses after a specified period.</p><p>Strict liability can apply without proof of negligence. Exam materials sometimes describe liability for abnormally dangerous activities as absolute. Vicarious liability attaches through a relationship, such as employer and employee. Identify what creates liability before deciding which policy responds.</p><details><summary>Reveal memory cue</summary><blockquote>Pure risk has no upside. Vacancy asks what’s left inside.</blockquote></details><h3>Apply the rule</h3><p>A furnished home is empty while the owner is away for a week. Which condition does this illustrate?</p><details><summary>Check answer</summary><p>Ordinary unoccupancy. Check the actual policy’s definitions and facts before applying any vacancy restriction.</p></details>"}, {"id": "outline-3", "title": "Property policy terms and federal rules", "html": "<small>GENERAL KNOWLEDGE · 13 SCORED QUESTIONS IN THIS SECTION</small><h2>Property policy terms and federal rules</h2><p><b>Read with core lessons 2, 16.</b></p><p>A representation is information given as true to the applicant’s knowledge. A warranty is an affirmation or promise treated as a policy requirement under the contract and applicable law. Concealment is failure to disclose a material fact. Underwriters may use applications, inspections, prior-loss reports and permissible consumer reports. The application identifies who and what is being insured and gives material details about the risk. Misstatements can affect coverage under applicable law.</p><p>Under the Fair Credit Reporting Act, insurers need a permissible purpose to obtain a consumer report. An adverse action based in whole or part on the report triggers notice and information about report access and dispute rights. Gramm-Leach-Bliley concerns protection of nonpublic personal information, privacy notices and applicable limits on sharing. Coverage territory tells you where the policy responds.</p><p>Check insured status before limits. A named insured is listed. Additional insured status arises from policy terms or endorsement. Other-insurance clauses may allocate by contribution or make a policy excess. TRIA establishes a federal backstop for qualifying commercial terrorism losses and requires insurers to make covered terrorism insurance available on eligible lines under program rules.</p><details><summary>Reveal memory cue</summary><blockquote>Application gives facts. Policy gives promises. Territory gives boundaries.</blockquote></details><h3>Apply the rule</h3><p>An insurer increases a premium based in part on a consumer report. Which federal law addresses the adverse-action notice?</p><details><summary>Check answer</summary><p>FCRA. Its notice requirements help the consumer find and dispute information in the report.</p></details>"}, {"id": "outline-4", "title": "Casualty policies and bonds", "html": "<small>GENERAL KNOWLEDGE · 23 SCORED QUESTIONS IN THIS SECTION</small><h2>Casualty policies and bonds</h2><p><b>Read with core lessons 8–9, 11–16.</b></p><p>On a CGL, a slip in a store is a premises exposure and an injury during an installation is an operations exposure. Work completed earlier or a product sold to a customer can trigger products-completed operations. Check named and additional insureds and their roles. The first named insured commonly handles notices and premiums. Per-occurrence limits cap one event. Aggregate limits cap a category of claims over a period. Supplementary payments can include defense costs and specified expenses under the form. A special damage-to-property-of-others provision, where provided, has its own terms. Review exclusions for property in the insured’s care, custody or control.</p><p>In personal auto, check the named insured, resident family members and permissive users against the specific coverage. A temporary substitute usually replaces an eligible auto out of normal use because of breakdown, repair, servicing, loss or destruction. A newly acquired auto has coverage-dependent notice rules. Transportation expenses or rental reimbursement depend on a qualifying loss, applicable daily and total limits and waiting terms. Specified causes of loss cover listed causes. Common exclusions can involve intentional injury, certain business uses or use without permission. The Auto Dealers form addresses dealer exposures and garagekeepers addresses customers’ cars in custody. Individual Named Insured and Drive Other Car endorsements address different personal-use gaps. Check whether equipment is a covered auto or mobile equipment before selecting the policy.</p><p>Workers’ comp Part Three can extend statutory coverage to listed other states subject to policy conditions. Exclusive remedy generally channels covered work injuries to statutory benefits subject to exceptions. In crime, theft is unlawful taking. Forgery involves unauthorized signing and alteration changes a document. Mysterious disappearance lacks evidence of what happened. Fidelity coverage addresses dishonest acts. Medical malpractice is professional liability for medical services. Liquor liability addresses covered claims arising from furnishing alcohol. Funds-transfer fraud involves unauthorized instructions to a financial institution. Review crime and cyber wording for coverage of a voluntary transfer induced by deception.</p><details><summary>Reveal memory cue</summary><blockquote>Ask whose car, whose injury, whose money and when it happened.</blockquote></details><h3>Apply the rule</h3><p>A company has a $1 million occurrence limit and only $300,000 left in the applicable aggregate. Its next separate covered occurrence results in $450,000 in damages. How much is available under those limits?</p><details><summary>Check answer</summary><p>$300,000, assuming no other coverage or adjustments. The aggregate remaining is the tighter limit.</p></details>"}, {"id": "outline-5", "title": "Casualty insurance concepts", "html": "<small>GENERAL KNOWLEDGE · 15 SCORED QUESTIONS IN THIS SECTION</small><h2>Casualty insurance concepts</h2><p><b>Read with core lessons 1–4, 10, 12–16.</b></p><p>An auditable policy may begin with a deposit premium based on estimated payroll, revenue or another exposure. The insurer audits actual exposure at the end and recalculates premium subject to policy minimums and rates. An occurrence may include repeated exposure to substantially the same conditions under the form. Limits and trigger language tell you whether claims share an occurrence.</p><p>A certificate can show insurance in force when issued but policy wording and endorsements control. A binder can supply temporary coverage subject to its stated terms. The loss valuation and application concepts from the property lessons also apply here, including the permissible use of consumer reports and notices following adverse action.</p><p>A victim’s bills and lost wages are special compensatory damages. Pain and suffering is general compensatory damage. Punitive damages punish or deter misconduct. Their insurability depends on the jurisdiction, facts and policy.</p><details><summary>Reveal memory cue</summary><blockquote>Estimate first. Audit actuals later.</blockquote></details><h3>Apply the rule</h3><p>A workers’ comp policy starts on an estimate of $400,000 payroll and the audit identifies $500,000 of eligible payroll at the same rates. What happens?</p><details><summary>Check answer</summary><p>The insurer recalculates using actual eligible exposure. Additional premium may be due subject to classifications and policy minimums.</p></details>"}, {"id": "outline-6", "title": "Casualty policy provisions", "html": "<small>GENERAL KNOWLEDGE · 12 SCORED QUESTIONS IN THIS SECTION</small><h2>Casualty policy provisions</h2><p><b>Read with core lessons 2, 12, 16, 18.</b></p><p>Read declarations, coverage agreement, conditions, exclusions, endorsements and definitions together. Notice tells the insurer a claim occurred. Proof of loss documents the loss formally when required. Duties can include cooperating, preserving evidence, forwarding legal papers and avoiding voluntary payments. Identify whose obligations the condition describes.</p><p>Other insurance determines priority or shares limits between policies. Subrogation lets the paying insurer seek recovery from a responsible third party. Supplementary payments can cover specified defense-related expenses. Cancellation and nonrenewal provisions determine timing and notice, subject to state law.</p><p>Liability insurers can have settlement authority under the policy. Professional liability can require the insured’s consent. A hammer clause may limit the insurer’s financial responsibility if the insured rejects a recommended settlement. Commercial terrorism coverage follows TRIA where applicable.</p><details><summary>Reveal memory cue</summary><blockquote>Notice alerts. Proof substantiates. Consent authorizes.</blockquote></details><h3>Apply the rule</h3><p>A professional refuses a recommended settlement. Which wording determines the effect of that refusal?</p><details><summary>Check answer</summary><p>The consent-to-settle condition and any hammer clause. Check whether and how the refusal affects later defense costs and indemnity.</p></details>"}, {"id": "outline-7", "title": "Texas rules common to P&C", "html": "<small>TEXAS RULES · 18 SCORED QUESTIONS IN THIS SECTION</small><h2>Texas rules common to P&C</h2><p><b>Read with core lessons 17–18.</b></p><p>The commissioner can examine records, investigate violations, conduct or initiate proceedings under applicable notice and hearing rules, and impose authorized penalties or cease-and-desist orders. A certificate of authority authorizes an insurer to transact insurance. Transaction includes activities such as soliciting, negotiating or carrying out insurance business. Domestic, foreign and alien describe formation in Texas, another US jurisdiction and outside the US. Admitted status concerns Texas authority. A stock insurer has shareholders, a mutual generally has policyholder members and Texas Lloyds operates through underwriters under a Lloyds plan.</p><p>Match the authority to the job. Agent and agency licensing are separate. Nonresident licensing relies on applicable home-state qualifications. Temporary and emergency authority have distinct grounds and time limits. Limited licenses restrict the scope of activity. Managing general agents exercise delegated insurer functions. Surplus lines agents place eligible nonadmitted coverage. Adjusters investigate or handle claims. Risk managers perform regulated risk-management services. Exemptions under §4002.003 depend on the activity and circumstances. Check appointment, renewal and CE requirements and applicable exemptions. Maintain records under §4001.255. Report address changes, felony convictions and administrative actions as required. Denial occurs at application, suspension interrupts authority and revocation withdraws it.</p><p>Differentiate false advertising, misrepresentation, defamation and fraudulent conduct. Controlled business rules address licensing primarily to insure one’s own or related interests. Rebating concerns prohibited purchase inducements. Unfair discrimination and coercion are distinct prohibited practices. Underwriting selects risks. Rating prices them using applicable rules. Commission sharing and unlicensed referrals have separate restrictions. Review TIC Chapters 541, 542, 544 and §§4001.104, 4001.157 and 4005.053–.054 for the boundaries.</p><details><summary>Reveal memory cue</summary><blockquote>Insurer needs authority. Producer needs the right license and appointment. Ask what conduct triggered enforcement.</blockquote></details><h3>Apply the rule</h3><p>An applicant wants to adjust claims and assumes their sales appointment authorizes it. What do you verify?</p><details><summary>Check answer</summary><p>The activity and the adjuster licensing requirements or applicable exemption. The authority to sell insurance is tied to a different role.</p></details><p><a href=\"https://statutes.capitol.texas.gov/\">Texas statutes</a> · <a href=\"https://www.tdi.texas.gov/\">Texas Department of Insurance</a></p>"}, {"id": "outline-8", "title": "Texas line-specific P&C rules", "html": "<small>TEXAS RULES · 12 SCORED QUESTIONS IN THIS SECTION</small><h2>Texas line-specific P&C rules</h2><p><b>Read with core lessons 7–9, 14, 18–19.</b></p><p>Use 28 TAC §5.5002 for technical P&C definitions and the applicable insurance code provisions for rate and form filing or approval. Surplus lines uses eligible nonadmitted insurers and licensed placement when statutory conditions are met. Differentiate declination, midterm cancellation and expiration nonrenewal. Under Insurance Code Chapter 551, check the policy line, time in force, permitted grounds, notice timing and delivery. For eligible homeowners risks, the FAIR Plan provides access to residential property coverage. TWIA covers eligible wind and hail exposure in designated areas. Review the Chapter 542 prompt-payment timeline and §862.053 for total fire loss of insured real property.</p><p>Transportation Code Chapter 601 governs proof of financial responsibility, including liability insurance or qualifying alternatives such as a bond, deposit or self-insurance under applicable provisions. Apply 30/60/25 in order. Distinguish PIP from UM/UIM and obtain a written rejection where applicable. TAIPA provides basic coverage to eligible drivers turned down by two insurers. TDI’s consumer guidance states that personal auto cancellation generally requires at least 10 days’ notice and nonrenewal requires at least 60 days’ notice. Remember that the first 60 days of a policy concern underwriting and permissible cancellation grounds. The separate 60-day nonrenewal rule measures advance notice before expiration. For rideshare under Chapter 1954, track whether the driver is off app, available in the app or on a prearranged ride. The two app-on phases have different liability requirements. Read the statute when comparing limits. For homeowners, use TDI’s home guide to compare the early underwriting period, cancellation reasons and notice, and the nonrenewal rules for the policy’s issue or renewal date.</p><p>Texas Labor Code Title 5 distinguishes covered work injuries and available medical, income, death and burial benefits. Income benefits include temporary, impairment, supplemental and lifetime categories with different triggers. The guaranty association addresses eligible claims in member-insurer insolvency. The medical liability JUA addresses eligible applicants seeking professional liability coverage. Compare the applicant, peril and statutory trigger before choosing a program.</p><details><summary>Reveal memory cue</summary><blockquote>App on changes auto exposure. Insolvency points to guaranty. Coastal wind points to TWIA.</blockquote></details><h3>Apply the rule</h3><p>A driver has turned on a rideshare app and is waiting for a request. Which statutory phase applies?</p><details><summary>Check answer</summary><p>The logged-on, available phase. The accepted-ride phase begins when the driver accepts a ride request.</p></details><p><a href=\"https://statutes.capitol.texas.gov/\">Texas statutes</a> · <a href=\"https://www.tdi.texas.gov/\">Texas Department of Insurance</a> · <a href=\"https://www.tdi.texas.gov/pubs/consumer/cb020.html\">Texas auto rules</a> · <a href=\"https://www.tdi.texas.gov/pubs/consumer/cb025.html\">Texas homeowners rules</a></p>"}, {"id": "ready", "title": "Check whether you’re ready", "html": "<h2>Check whether you’re ready</h2><p>From memory, identify HO and DP coverages, work a coinsurance and split-limit calculation, match common commercial claims to policies and explain the Texas licensing and claims rules. Explain each answer and the clue that led to it.</p><p>Use a fresh full-length practice exam from an exam-prep provider under the 150-minute limit. Aim for at least 80% on two fresh timed attempts as an internal study target. This course’s 16-question drill helps identify weak areas. The official exam reports a scaled score. If you miss the practice target, review your weakest sections and try a different set before sitting the exam.</p>"}]','[{"prompt": "Hail dents an insured’s parked car. Which coverage responds?", "choices": ["PIP", "Other-than-collision", "Collision", "Property damage liability"]}, {"prompt": "An HO-3 question describes a stolen sofa. Where do you check for the cause of loss?", "choices": ["Personal liability provisions", "Other structures limit", "Contents named-perils provisions", "Dwelling open-perils provisions"]}, {"prompt": "Which home form fits an owner who lives in a condominium unit?", "choices": ["HO-4", "DP-1", "HO-8 automatically", "HO-6"]}, {"prompt": "An attached garage burns. Which homeowners property coverage applies first?", "choices": ["A", "B", "C", "D"]}, {"prompt": "Ignoring a broken lock because insurance will pay shows what?", "choices": ["Indirect loss", "Morale hazard", "Moral hazard", "Peril"]}, {"prompt": "A company’s sales rep drives the company-owned pickup and injures someone. The employer is held responsible for the rep’s conduct. What kind of liability?", "choices": ["Contractual indemnity only", "Absolute in all cases", "Vicarious", "First-party"]}, {"prompt": "A professional’s policy requires both a first-made claim and reporting within the specified period. Which dates should you inspect?", "choices": ["Invoice date only", "Payment date only", "Lawsuit verdict only", "Claim, report and applicable retroactive date"]}, {"prompt": "A shop’s loss is $10,000 before deductible. It carries $100,000 against a $200,000 coinsurance requirement. Deductible $500. Payment?", "choices": ["$4,500", "$5,000", "$9,500", "$4,750"]}, {"prompt": "A client thinks $25,000 in 30/60/25 will repair her own truck after she hits a fence. What does that limit cover?", "choices": ["All passengers’ injuries", "Liability for others’ property per accident", "Her collision damage", "Her medical bills"]}, {"prompt": "An insurer chooses to let a policy expire instead of continuing it. What occurred?", "choices": ["Rescission", "Declination of a new applicant", "Nonrenewal", "Cancellation"]}, {"prompt": "A customer’s car is damaged while held by a repair shop. Which coverage should the shop examine?", "choices": ["Employee dishonesty", "BOP business income", "Motor carrier cargo automatically", "Garagekeepers"]}, {"prompt": "A Texas policyholder rejects PIP during a phone call. What is missing?", "choices": ["A written rejection", "A collision deductible", "Proof of vehicle ownership", "A guaranty association filing"]}, {"prompt": "An insurer incorporated in Oklahoma is authorized in Texas. How does Texas classify its domicile?", "choices": ["Unauthorized", "Foreign", "Alien", "Domestic"]}, {"prompt": "A covered employee injury produces hospital bills and missed work. Which two benefit categories fit?", "choices": ["Collision and PIP", "Liability and salvage", "Medical and income", "Burial and death"]}, {"prompt": "A jeweler’s bookkeeper secretly diverts the store’s receipts. Which exposure fits?", "choices": ["Robbery", "Products liability", "Surety performance", "Employee theft"]}, {"prompt": "A resident applicant passes the exam. What is the next TDI step on the ordinary individual path?", "choices": ["Begin TDI’s fingerprint process", "Start selling immediately", "Apply for CE credit", "Obtain a carrier certificate of authority"]}]','BCDABCDABCDABCDA'),
('student-loan','Student Loan Advisor Training','[{"id": "m01", "title": "01 Downloading and reading NSLDS records", "html": "<h3>01 Downloading and reading NSLDS records</h3><p><strong>What you’ll learn.</strong> Reconcile a federal export to a working loan inventory.</p><p>National Student Loan Data System records are visible through the borrower’s StudentAid.gov account. Have the borrower sign in privately, open My Aid and use the data-download option. Read loan type, first disbursement date, original amount, current balance, holder and status history. Reconcile current payments and accrued interest against statements. Use official PSLF records for counts. Keep a dated original and a redacted working inventory in approved storage.</p><h4>How to apply it</h4><p>Start with a borrower-controlled download. Identify original loan IDs, then mark active, paid through consolidation, and otherwise closed rows. Compare the remaining accounts to a statement dated as close as possible to the export. Confirm suspected transfers with the servicer.</p><div class=\"check\"><strong>Worked example</strong><p>An old loan shows zero and a consolidation shows $32,000. Before totaling the file, trace whether consolidation paid off the old loan. Capture both as history, with the outstanding balance attributed once.</p></div>"}, {"id": "m02", "title": "02 Federal student loan programs", "html": "<h3>02 Federal student loan programs</h3><p><strong>What you’ll learn.</strong> Classify loans before choosing a relief program.</p><p>Direct Subsidized loans are for eligible undergraduates with financial need. Direct Unsubsidized loans accrue interest during school and can serve eligible undergraduate and graduate borrowers. Parent PLUS belongs to the signing parent. Grad PLUS belongs to the graduate borrower and is being phased out for new borrowers subject to exceptions. FFEL and Perkins are legacy federal programs with different holders and access to federal benefits.</p><h4>How to apply it</h4><p>Group records by legal borrower first, then source program and current holder. Resolve any school-originated account using the note and school records. A private lender can service a legacy federal loan, so the lender name alone is insufficient.</p><div class=\"check\"><strong>Worked example</strong><p>A nurse holds Direct, Perkins and private debt. PSLF is a Direct Loan program. Check Perkins cancellation before proposing consolidation and keep private debt separate.</p></div>"}, {"id": "m03", "title": "03 Federal borrowing limits and eligibility", "html": "<h3>03 Federal borrowing limits and eligibility</h3><p><strong>What you’ll learn.</strong> Distinguish a program cap from the borrower’s actual award.</p><p>Distinguish annual limits, aggregate limits, remaining eligibility and the school’s actual award. Undergraduate limits vary by year and dependency status. For borrowers subject to the new rules, general graduate caps are $20,500 annually and $100,000 aggregate, professional caps $50,000 and $205,000, and Parent PLUS caps $20,000 per year and $65,000 aggregate per dependent student. Check exception status, enrollment intensity, prior borrowing and classification with the school.</p><h4>How to apply it</h4><p>Check program classification, exception status, dependency, attendance level, prior borrowing, net cost and other aid. Apply annual and aggregate limits separately. Get a dated confirmation from the school before telling a family how much they can borrow.</p><div class=\"check\"><strong>Worked example</strong><p>A program calls itself professional in its brochure. The financial aid office must confirm how it is classified under federal rules before you model the higher cap.</p></div>"}, {"id": "m04", "title": "04 Interest rates on federal loans", "html": "<h3>04 Interest rates on federal loans</h3><p><strong>What you’ll learn.</strong> Calculate loan interest and pick the right rate vintage.</p><p>Use first disbursement date and loan type to select the rate. For July 1, 2026 through June 30, 2027, fixed rates are 6.52% for undergraduate Direct Subsidized and Unsubsidized, 8.07% for graduate or professional Direct Unsubsidized, and 9.07% for Direct PLUS. Origination fees can reduce the amount delivered while the borrower owes the gross loan principal.</p><h4>How to apply it</h4><p>Match the rate to the first disbursement and loan type. Convert the annual rate to a decimal and multiply it by principal and elapsed days divided by the applicable day-count basis. Compare the resulting accrual with the servicer history.</p><div class=\"check\"><strong>Worked example</strong><p>$20,000 at 6.52% accrues about $3.57 daily using 365.25 days. Use the servicer’s posting and day basis for a live payoff.</p></div>"}, {"id": "m05", "title": "05 Applying for federal aid and loans", "html": "<h3>05 Applying for federal aid and loans</h3><p><strong>What you’ll learn.</strong> Walk a student from FAFSA to a documented disbursement.</p><p>The borrower completes FAFSA, reviews the aid offer with the school, accepts only what is needed, and completes any required entrance counseling and Master Promissory Note. Determine whether a Parent PLUS or eligible legacy Grad PLUS application has additional steps. Confirm school deadlines, disbursement schedule and whether an existing default requires resolution.</p><h4>How to apply it</h4><p>Confirm which academic year is needed. List grants and scholarships first, estimate uncovered cost, then compare available federal loans, fees and timing. Check the aid offer, acceptance, counseling and signed note. The school confirms disbursement.</p><div class=\"check\"><strong>Worked example</strong><p>A student needs $8,000 after grants and is offered $12,000. Confirm the budget, expected fees and school rules before accepting the necessary amount.</p></div>"}, {"id": "m06", "title": "06 Private and other nonfederal loans", "html": "<h3>06 Private and other nonfederal loans</h3><p><strong>What you’ll learn.</strong> Compare private debt terms with borrower cash flow.</p><p>Read the promissory note and current statement for rate type, index and margin, term, cosigner release, hardship options and discharge terms. State or institutional loans may have distinct terms. Private contracts generally do not provide federal IDR or PSLF. Compare offers by APR, term, payment, total cost and protections.</p><h4>How to apply it</h4><p>Collect the current statement and note. Verify index, margin, reset frequency, cap, cosigner terms and hardship policy. Calculate base and adverse cash flow, and compare any refinance quote at the same repayment term.</p><div class=\"check\"><strong>Worked example</strong><p>A variable-rate borrower owes $25,000. A two-point rate increase adds roughly $500 in annual interest at that balance before amortization.</p></div>"}, {"id": "m07", "title": "07 Comparing federal consolidation and private refinancing", "html": "<h3>07 Comparing federal consolidation and private refinancing</h3><p><strong>What you’ll learn.</strong> Explain consolidation and private refinancing in client language.</p><p>Direct Consolidation pays off included federal loans with a new federal loan. Its weighted rate generally rounds up to the next eighth of a percentage point. It can change repayment eligibility, cost, payment counts and other benefits. Private refinancing pays off included debt with a private loan. Refinancing federal loans privately generally forfeits federal protections on those loans.</p><div class=\"wide\"><table><thead><tr><th scope=\"col\">Choice</th><th scope=\"col\">What changes</th></tr></thead><tbody><tr><td>Keep current loans</td><td>Preserves the current products, subject to existing rules.</td></tr><tr><td>Direct Consolidation</td><td>Creates a new federal loan. Verify rates, eligible plans, and counts.</td></tr><tr><td>Private refinance</td><td>Creates private debt. Federal protections on included balances generally end.</td></tr></tbody></table></div><h4>How to apply it</h4><p>Show the included loans, new product, weighted rate, principal after capitalization and repayment history. Compare forgiveness, hardship and discharge effects before approval. Use a written before-and-after table for federal debt going into a private quote.</p><div class=\"check\"><strong>Worked example</strong><p>$30,000 at 5% and $20,000 at 7% produce 5.8% weighted, rounded up to 5.875%. Model keeping the loans separate before acting.</p></div>"}, {"id": "m08", "title": "08 When accrued interest becomes principal", "html": "<h3>08 When accrued interest becomes principal</h3><p><strong>What you’ll learn.</strong> Distinguish interest accrual from capitalization.</p><p>Unpaid interest and principal are separate until a capitalization event adds interest to principal. Future interest then accrues on the larger base. Verify the trigger for the loan and the current rule. Forbearance may result in interest accrual even when capitalization does not occur immediately.</p><h4>How to apply it</h4><p>Use current principal and accrued interest as separate inputs. Look for a documented capitalization event and reconcile the next statement. Do not add unpaid interest to principal automatically in your model.</p><div class=\"check\"><strong>Worked example</strong><p>If $2,000 capitalizes on $40,000 at 6%, annual simple interest rises by $120 at the new principal. Confirm whether the $2,000 actually capitalized before modeling.</p></div>"}, {"id": "m09", "title": "09 Weighted averages and payment allocation", "html": "<h3>09 Weighted averages and payment allocation</h3><p><strong>What you’ll learn.</strong> Distinguish amount owed, payment posting and blended rates.</p><p>Distinguish the weighted consolidation rate, weighted forgiveness count and the servicer’s allocation of a payment across loan groups. A $400 payment allocated strictly in proportion to $15,000 and $5,000 balances would be $300 and $100. The servicer can use different allocation rules and loan-level charges. Check instructions for extra payments, amounts past due and whether the next bill advances.</p><h4>How to apply it</h4><p>First satisfy amounts due across groups. Then ask which group receives any extra, when the servicer advances the due date, and how fees and interest are applied. Verify the posting from transaction history.</p><div class=\"check\"><strong>Worked example</strong><p>Before targeting a high-rate loan, confirm the required payment on all groups, provide permitted borrower instructions, and check the actual posting.</p></div>"}, {"id": "m10", "title": "10 Grace periods and payment pauses", "html": "<h3>10 Grace periods and payment pauses</h3><p><strong>What you’ll learn.</strong> Assess the cost and consequences of a temporary payment pause.</p><p>A grace period follows specified enrollment changes for eligible loans. Deferment depends on a qualifying condition. Forbearance pauses or reduces scheduled payments under applicable rules. Interest treatment, count credit and expiration vary by program and status. Identify the specific effective dates and first bill.</p><h4>How to apply it</h4><p>Identify pause type, eligible period, interest treatment and whether particular months can count. List the end date and first bill. Compare pause, recertification and another available plan when the borrower’s income drops.</p><div class=\"check\"><strong>Worked example</strong><p>A pause lasts four months on $30,000 at 6%. Approximate accrued interest is $600 if all interest accrues to the borrower and principal stays flat. Ask whether any month counts toward forgiveness.</p></div>"}, {"id": "m11", "title": "11 How income-driven repayment evolved", "html": "<h3>11 How income-driven repayment evolved</h3><p><strong>What you’ll learn.</strong> Translate a historical plan name into a current decision.</p><p>IDR bases payments on income and plan-specific household inputs. Older programs included ICR, IBR, PAYE and REPAYE. SAVE replaced REPAYE and was ended by court order in March 2026. RAP became available in July 2026. An account may show historical plan names. Use the history to investigate credits and current rules to verify today’s choices.</p><h4>How to apply it</h4><p>Build a plan timeline including entry and exit dates and repayment status. Match each historical plan to the applicable rule then check today’s eligible options. Ask whether billing and payment counts moved after the transition.</p><div class=\"check\"><strong>Worked example</strong><p>A 2024 statement says SAVE. Record it as historical evidence and retrieve the current plan and transition notice.</p></div>"}, {"id": "m12", "title": "12 Graduated fixed repayment", "html": "<h3>12 Graduated fixed repayment</h3><p><strong>What you’ll learn.</strong> Evaluate a graduated payment schedule.</p><p>A graduated schedule starts lower and generally steps up every two years. Review plan eligibility and the actual step schedule. Compared with level repayment, lower early principal reduction can increase lifetime interest. Test future payments against a realistic earnings path.</p><h4>How to apply it</h4><p>Request the actual schedule and compare every step with a flat-income budget. Sum the scheduled payments over the applicable term and stress-test planned income increases. Confirm any PSLF eligibility independently.</p><div class=\"check\"><strong>Worked example</strong><p>A client can handle $350 today but the quote reaches $650. Ask how they would handle the step-up if income stayed flat.</p></div>"}, {"id": "m13", "title": "13 Extended level repayment", "html": "<h3>13 Extended level repayment</h3><p><strong>What you’ll learn.</strong> Quantify the trade-off in extended level repayment.</p><p>Legacy federal Extended repayment can stretch eligible repayment to up to 25 years. Its eligibility typically requires more than $30,000 in outstanding loans within the applicable program and other conditions. Compare with Standard and eligible IDR. A longer term can buy near-term affordability while raising total cost.</p><h4>How to apply it</h4><p>Verify program-level balance and plan eligibility, then compare level payments and lifetime interest at the same rate. Add an optional extra-payment scenario if the client wants lower required payments with flexibility.</p><div class=\"check\"><strong>Worked example</strong><p>$40,000 at 6% is about $444 monthly over 10 years versus $258 over 25 years using level-payment math. Total modeled payments are roughly $53,300 and $77,300.</p></div>"}, {"id": "m14", "title": "14 Extended repayment with graduated payments", "html": "<h3>14 Extended repayment with graduated payments</h3><p><strong>What you’ll learn.</strong> Evaluate extended graduated payments against a flat alternative.</p><p>The extended graduated option combines a longer eligible term with rising payments over several repayment steps. Request the full amortization schedule, calculate total dollars, and stress-test each increase. Compare that schedule with extended fixed repayment and eligible income-based choices.</p><h4>How to apply it</h4><p>Collect the starting, step-up and highest payments for the full term. Compare total payments and the dates on which the schedule would strain cash flow. Include a path for reassessment before the next increase.</p><div class=\"check\"><strong>Worked example</strong><p>The starting bill is $260 and the highest is $620. Separate the cash-flow improvement today from the future income needed to sustain it.</p></div>"}, {"id": "m15", "title": "15 Tiered Standard repayment", "html": "<h3>15 Tiered Standard repayment</h3><p><strong>What you’ll learn.</strong> Map eligible balances to a Tiered Standard term.</p><p>The post-cutoff fixed plan uses a term based on the applicable Direct Loan balance. General terms are 10 years below $25,000, 15 years from $25,000 to below $50,000, 20 years from $50,000 to below $100,000, and 25 years from $100,000. Confirm the balance definition and eligibility. Tiered Standard payments do not qualify for PSLF.</p><div class=\"wide\"><table><thead><tr><th scope=\"col\">Applicable principal</th><th scope=\"col\">General maximum term</th></tr></thead><tbody><tr><td>Under $25,000</td><td>10 years</td></tr><tr><td>$25,000 to under $50,000</td><td>15 years</td></tr><tr><td>$50,000 to under $100,000</td><td>20 years</td></tr><tr><td>$100,000 and above</td><td>25 years</td></tr></tbody></table></div><h4>How to apply it</h4><p>Identify which Direct loans determine the applicable balance, then confirm whether the borrower falls under the post-cutoff fixed framework. Compare that term with eligible RAP and check PSLF consequences separately.</p><div class=\"check\"><strong>Worked example</strong><p>A qualifying borrower has $55,000 entering repayment. Model the 20-year tier and compare RAP if eligible.</p></div>"}, {"id": "m16", "title": "16 Who does what in student loan servicing", "html": "<h3>16 Who does what in student loan servicing</h3><p><strong>What you’ll learn.</strong> Route a billing or eligibility problem to the right party.</p><p>The federal dashboard provides program records. The servicer handles bills and processing. A defaulted account may be handled by the Default Resolution Group or a guaranty agency. The school confirms aid eligibility and disbursement. Route discrepancies first to the responsible party, then to the relevant FSA feedback or ombudsman channel if unresolved.</p><h4>How to apply it</h4><p>Use servicers for billing and posting, FSA for federal program tracking, the school for aid, and the holder, DRG or guaranty agency for default as applicable. Preserve receipts, names and case numbers. Escalate unresolved errors through the appropriate official channel.</p><div class=\"check\"><strong>Worked example</strong><p>A correct federal balance appears alongside a misapplied payment. Keep the receipt and transaction history, request correction from the servicer and log its case number.</p></div>"}, {"id": "m17", "title": "17 Auditing eligibility for PSLF buyback", "html": "<h3>17 Auditing eligibility for PSLF buyback</h3><p><strong>What you’ll learn.</strong> Determine when a PSLF buyback request is worth pursuing.</p><p>Map and certify employment by month using the PSLF Help Tool. Buyback applies to certain otherwise excluded deferment or forbearance months on eligible outstanding Direct loans when there are already 120 qualifying employment months and the purchase would result in forgiveness. Check disbursement and consolidation history. If FSA issues an agreement, follow its payment deadline and preserve proof.</p><ol class=\"steps\"><li>120 certified employment months</li><li>Eligible months on current Direct loan</li><li>Buyback would complete PSLF</li><li>Follow the agreement</li></ol><h4>How to apply it</h4><p>Audit certified employment by month and identify eligible deferment or forbearance months on the outstanding Direct loan. Verify the current plan during those months, consolidation history and whether buyback achieves discharge. Compare with ordinary qualifying payments.</p><div class=\"check\"><strong>Worked example</strong><p>At 116 qualifying payments and 120 approved employment months, audit four uncovered months. Months on loans before the current consolidation cannot be bought back on that new loan.</p></div>"}, {"id": "m18", "title": "18 Household size and dependents across plans", "html": "<h3>18 Household size and dependents across plans</h3><p><strong>What you’ll learn.</strong> Use the correct household inputs for each plan.</p><p>IBR uses plan-defined family size with an applicable poverty guideline. RAP uses a dollar reduction per eligible dependent claimed on a federal return. Filing status, spouse income, spouse debt and dependent rules can differ. Build a dated input record for each plan instead of carrying one headcount across both calculations.</p><h4>How to apply it</h4><p>Create separate rows for plan-based family size, return-claimed dependents, filing status and applicable spouse income and eligible debt. Ask who claimed each dependent and confirm any separate-filing or joint calculation rules. Save dated evidence.</p><div class=\"check\"><strong>Worked example</strong><p>A client supports a relative who is not claimed on the tax return. Verify IBR treatment independently and omit the RAP deduction unless federal eligibility is established.</p></div>"}, {"id": "m19", "title": "19 Choosing between RAP and IBR", "html": "<h3>19 Choosing between RAP and IBR</h3><p><strong>What you’ll learn.</strong> Decide between IBR and RAP using the whole repayment path.</p><p>Compare payment now, annual recertification risk, interest treatment, projected balance and time to forgiveness. RAP offers a rules-based interest waiver and principal contribution for qualifying payments. IBR can have a shorter forgiveness term and a cap tied to the 10-year Standard calculation. Use loan type and dates to establish that both are available.</p><h4>How to apply it</h4><p>Compare payment, interest and principal behavior, credited months, income changes and estimated payoff or forgiveness. Run probabilities or discrete downside scenarios without treating forgiveness as guaranteed. Use a common cash horizon before comparing totals.</p><div class=\"check\"><strong>Worked example</strong><p>At $75,000 AGI and two qualifying RAP dependents, 7% yields $337.50 monthly. If verified IBR is $325, compare official counts, the remaining term and cash cost before choosing.</p></div>"}, {"id": "m20", "title": "20 How RAP fits into the IDR timeline", "html": "<h3>20 How RAP fits into the IDR timeline</h3><p><strong>What you’ll learn.</strong> Connect historical repayment changes to an individual loan timeline.</p><p>Build milestones by borrower cohort. Record the end of SAVE in March 2026, the July 2026 rollout of RAP and Tiered Standard, and retirement of legacy PAYE and ICR no later than July 1, 2028. Some legacy options remain available for eligible pre-cutoff borrowers. New loans and consolidations can change the available set.</p><h4>How to apply it</h4><p>Use three separate milestones for end of SAVE, July 2026 eligibility changes and July 2028 legacy sunset. Date any proposed consolidation or new first disbursement. Record whether it changes the borrower’s choices before proceeding.</p><div class=\"check\"><strong>Worked example</strong><p>A borrower expects to enroll in school next year. Add the potential new first disbursement to the model and reassess plan access before committing to an enrollment-dependent strategy.</p></div>"}, {"id": "m21", "title": "21 Reviewing the one-time account adjustment", "html": "<h3>21 Reviewing the one-time account adjustment</h3><p><strong>What you’ll learn.</strong> Audit existing IDR adjustment credit.</p><p>The past IDR account adjustment credited certain months under special rules. Treat it as historical account evidence. Compare FSA’s count with repayment, deferment, forbearance and consolidation records. Identify unexplained gaps, then use the official dispute or feedback route with documentary evidence.</p><h4>How to apply it</h4><p>Compare the account’s adjusted count with loan-level statuses and servicing history. Flag missing months with dates and evidence. Handle any potential corrections through the official channel and retain the response.</p><div class=\"check\"><strong>Worked example</strong><p>Online history suggests 108 months while the borrower recalls 120. Build a month-by-month ledger rather than treating the twelve-month gap as automatically eligible.</p></div>"}, {"id": "m22", "title": "22 The 10 percent IBR formula", "html": "<h3>22 The 10 percent IBR formula</h3><p><strong>What you’ll learn.</strong> Calculate capped 10 percent IBR.</p><p>Determine borrower vintage using actual disbursements and outstanding history. If the borrower qualifies, estimate 10% of annual discretionary income divided by 12, subject to the applicable 10-year Standard cap. The typical forgiveness horizon is 20 years of qualifying payments. Discretionary income generally subtracts 150% of the applicable poverty guideline.</p><h4>How to apply it</h4><p>Confirm the newer IBR cohort and usable AGI, subtract the applicable poverty allowance, apply 10%, divide by twelve and check the cap. Save the source of each input.</p><div class=\"check\"><strong>Worked example</strong><p>AGI $72,000 less a hypothetical $32,000 allowance gives $333.33 before a cap. If the verified cap is $300, the modeled amount is $300.</p></div>"}, {"id": "m23", "title": "23 The 15 percent legacy IBR formula", "html": "<h3>23 The 15 percent legacy IBR formula</h3><p><strong>What you’ll learn.</strong> Calculate capped legacy 15 percent IBR.</p><p>For the legacy IBR cohort, generally model 15% of discretionary income, subject to the applicable cap, and a 25-year qualifying payment term. Identify whether FFEL or Direct debt is involved and verify loan-plan fit. The same income can produce a very different payment in the two IBR cohorts.</p><h4>How to apply it</h4><p>Confirm the legacy cohort, actual program and cap. Calculate monthly payment with the 15% factor, then track the 25-year target and compare another plan only if eligible.</p><div class=\"check\"><strong>Worked example</strong><p>$36,000 of discretionary income gives $450 before the cap under 15% IBR and $300 under 10%. The borrower’s cohort determines which calculation applies.</p></div>"}, {"id": "m24", "title": "24 Repayment Assistance Plan mechanics", "html": "<h3>24 Repayment Assistance Plan mechanics</h3><p><strong>What you’ll learn.</strong> Calculate RAP and explain its mechanics.</p><p>RAP charges a percentage of AGI by bracket and reduces the monthly payment by $50 per eligible claimed dependent, with a $10 floor. Use the published bracket amount, not marginal tax bracket math. At AGI of $10,000 or less, the base is $10 monthly. Terms include 360 qualifying months and limited interest/principal protections for qualifying payments. Parent PLUS and consolidations containing it are excluded.</p><ol class=\"steps\"><li>Confirm eligible debt</li><li>Use applicable AGI bracket</li><li>Subtract dependent credit</li><li>Apply the $10 floor</li></ol><h4>How to apply it</h4><p>Confirm eligible Direct debt, select the rate using applicable AGI, divide by 12, subtract eligible dependent reductions and apply the floor. Model the balance with official rules for qualifying full and timely payments.</p><div class=\"check\"><strong>Worked example</strong><p>$85,000 at 8% with one eligible dependent gives $516.67 monthly. Log AGI, dependent source and bracket.</p></div>"}, {"id": "m25", "title": "25 Tracking forgiveness credit under RAP and IBR", "html": "<h3>25 Tracking forgiveness credit under RAP and IBR</h3><p><strong>What you’ll learn.</strong> Reconcile distinct IBR, RAP and PSLF targets.</p><p>Maintain separate IDR and PSLF counts per loan. Review the destination plan’s rules about which prior months can count and how a new consolidation changes the clock. The final RISE rule allows qualifying IBR payments and qualifying PAYE payments made before July 1, 2028, to count toward RAP under the stated conditions. Review <a href=\"https://www.ecfr.gov/current/title-34/subtitle-B/chapter-VI/part-685/subpart-B/section-685.209\">34 CFR 685.209</a> for other periods and exceptions. Keeping a previously earned month and having the same number of months remaining are different questions when the target changes from 240 to 360.</p><h4>How to apply it</h4><p>Record the old count, destination plan, months accepted under its rule, target and months remaining. Verify which payment types transfer under the final rule and compare the date to possible future borrowing.</p><div class=\"check\"><strong>Worked example</strong><p>If 144 months were verified as transferable, a 240-month target leaves 96 and a 360-month target leaves 216. Validate the premise before putting either date into a memo.</p></div>"}, {"id": "m26", "title": "26 Advanced IDR case analysis", "html": "<h3>26 Advanced IDR case analysis</h3><p><strong>What you’ll learn.</strong> Stress-test eligibility and payments across a mixed loan file.</p><p>For mixed histories, map loan type, holder, borrower, cutoff dates, current plans, status and credits before selecting any strategy. Run baseline, lower-income and higher-income projections. Flag cliff effects, the treatment of married borrowers, changes after recertification and exposure to discharge taxes.</p><h4>How to apply it</h4><p>Partition by holder, loan type, age and count. Create no-action, plan change, and eligible consolidation alternatives. Model low, base and high income and verify conditional approvals before taking irreversible action.</p><div class=\"check\"><strong>Worked example</strong><p>A borrower has older FFEL and newer Direct loans. Compare keeping loans separate with applicable federal consolidation. Identify access gained, legacy options lost and count impact.</p></div>"}, {"id": "m27", "title": "27 The RISE repayment rules", "html": "<h3>27 The RISE repayment rules</h3><p><strong>What you’ll learn.</strong> Use the final RISE rule to validate a plan change.</p><p>RISE is the Department of Education rulemaking implementing statutory changes. Separate statute, final regulation, effective date, agency implementation and individual servicer notice. Maintain a rule ledger with source, publication date, effective date and impacted borrower cohort. Review dated guidance before teaching a change.</p><h4>How to apply it</h4><p>Read the final regulation and effective-date provision. Compare agency materials to implementation and reconcile account evidence. Record the date on which the rule was checked.</p><div class=\"check\"><strong>Worked example</strong><p>A draft summary conflicts with final rule text. Use the final text and confirm effective timing and applicable borrower facts before relying on it.</p></div>"}, {"id": "m28", "title": "28 Worked IBR and RAP household cases", "html": "<h3>28 Worked IBR and RAP household cases</h3><p><strong>What you’ll learn.</strong> Explain the effect of changed dependents.</p><p>Case A claims two eligible RAP dependents and has $75,000 applicable AGI. RAP is $337.50. If a verified IBR poverty allowance is $36,000 and 10% applies, IBR is $325 before the cap. Case B has $44,000 applicable AGI and one eligible RAP dependent. At 4%, RAP is about $96.67. Recompute both for the correct filing and family inputs when facts change.</p><h4>How to apply it</h4><p>Run each household change through RAP and IBR separately. Verify filing and spouse inputs. Identify the date the changed facts are relevant to the borrower’s application and check what documentation is accepted.</p><div class=\"check\"><strong>Worked example</strong><p>In Case A, losing one RAP dependent adds $50 monthly if the floor does not bind. IBR must be recalculated using its own family-size rules.</p></div>"}, {"id": "m29", "title": "29 Payment timing and forgiveness records", "html": "<h3>29 Payment timing and forgiveness records</h3><p><strong>What you’ll learn.</strong> Track payments that support forgiveness.</p><p>Track due date, full amount due, date posted, plan, employment and official count. RAP PSLF timing rules can be strict, particularly for borrowers with post-cutoff loans. Avoid treating any late, partial, extra or paused month as qualifying without checking the applicable rule. Reconcile autopay and bank records after a plan change.</p><h4>How to apply it</h4><p>Capture due date, effective paid date, total required, plan, status and qualifying employer month. Watch first bills following a switch and reconcile posted payments to account records before claiming credit.</p><div class=\"check\"><strong>Worked example</strong><p>A bank receipt predates the due date but the servicer posted later. Keep evidence, ask how the servicer applied the effective date, and request correction if warranted.</p></div>"}, {"id": "m30", "title": "30 Student loan case intake", "html": "<h3>30 Student loan case intake</h3><p><strong>What you’ll learn.</strong> Convert a Valtoris Student Loan Report Card into verified intake.</p><p>Open with the borrower’s goal, deadline and immediate risk. The Valtoris Student Loan Report Card is a starting point. Verify its inputs against account evidence. Gather consent, household and employment facts, plan and notice history, loan statuses, estimated budget and referral needs. Enter confirmed and missing information separately in TAC.</p><h4>How to apply it</h4><p>Document the client’s objective and deadline first. Compare self-reported data to statements, obtain consent, and name each outstanding item in TAC. Triage collection, imminent billing and school deadlines.</p><div class=\"check\"><strong>Worked example</strong><p>A client wants the lowest payment and has a collections notice. Triage the notice first, record its date and route questions about legal rights or response deadlines to qualified counsel.</p></div>"}, {"id": "m31", "title": "31 Managing and documenting cases", "html": "<h3>31 Managing and documenting cases</h3><p><strong>What you’ll learn.</strong> Manage milestones from application through confirmed billing.</p><p>Move from intake through verification, modeling, review, borrower decision and follow-up. Document at least two viable paths when available. Name who will act, when and what will confirm completion. Explain that official forms are free. Borrowers control login, consent and submission. Have compliance review client-facing fees and marketing, including federal restrictions on advance fees for covered telemarketed debt relief.</p><ol class=\"steps\"><li>Intake</li><li>Verify</li><li>Compare</li><li>Borrower submits</li><li>Confirm plan and bill</li></ol><h4>How to apply it</h4><p>For each action assign a person, due date and proof. Separate submitted, approved and in effect. Use supervisor review for sensitive choices and document an approved fee or scope only after compliance review.</p><div class=\"check\"><strong>Worked example</strong><p>An IDR submission receipt arrives. Keep the case open until the borrower verifies processing, the new plan and first bill, or the planned follow-up confirms a delay.</p></div>"}, {"id": "m32", "title": "32 Helping clients retrieve loan documents", "html": "<h3>32 Helping clients retrieve loan documents</h3><p><strong>What you’ll learn.</strong> Help a client retrieve records without handling credentials.</p><p>Walk the borrower through StudentAid.gov and servicer navigation while they control the screen and credentials. Request only what is needed. Use secure transfer and approved access controls. Collect evidence of program, dates and counts plus the current bill and notices. Store a secure reference in TAC when the underlying document contains sensitive details.</p><h4>How to apply it</h4><p>Ask the borrower to sign in privately and use authorized secure transfer with minimum needed fields. For a screen-share, pause during authentication. Route accidental credential exposure through the approved process and direct secure account recovery.</p><div class=\"check\"><strong>Worked example</strong><p>A borrower texts a password and verification code. Do not use them. Route the exposure through your incident process and guide the borrower to secure their account.</p></div>"}, {"id": "m33", "title": "33 Understanding loan repayment assistance programs", "html": "<h3>33 Understanding loan repayment assistance programs</h3><p><strong>What you’ll learn.</strong> Evaluate loan repayment assistance as part of compensation.</p><p>Loan repayment assistance programs can provide money toward eligible debt under an employer, occupation, school or government program. Compare qualifying loans, employment rules, award schedule, tax treatment and obligations. A promised award is different from an executed award agreement.</p><h4>How to apply it</h4><p>Check qualifying debt, payment beneficiary, installment timing, service obligations, tax handling and exit terms. Get the benefit in writing before including it in a budget.</p><div class=\"check\"><strong>Worked example</strong><p>An employer advertises up to $10,000. Confirm whether private debt qualifies and when benefits vest before counting that amount in a job comparison.</p></div>"}, {"id": "m34", "title": "34 Employee benefits under Sections 125 and 127", "html": "<h3>34 Employee benefits under Sections 125 and 127</h3><p><strong>What you’ll learn.</strong> Distinguish Sections 125 and 127 when reviewing employee benefits.</p><p>Section 125 generally governs cafeteria plans that let eligible employees choose among cash and qualified benefits. Section 127 governs qualifying employer educational assistance, including qualifying student loan payments under a written program. A cafeteria-plan label alone does not establish a tax exclusion for loan repayment.</p><h4>How to apply it</h4><p>Identify the benefit under the written employer plan. Ask payroll whether the borrower and expense qualify. Review tax handling with the tax advisor and ensure the assistance is applied correctly to eligible debt.</p><div class=\"check\"><strong>Worked example</strong><p>HR calls a loan payment pretax. Ask for the written benefit terms and payroll treatment, then coordinate verification with a tax professional.</p></div>"}, {"id": "m35", "title": "35 Service based loan repayment programs", "html": "<h3>35 Service based loan repayment programs</h3><p><strong>What you’ll learn.</strong> Compare public service incentives and service-based repayment separately.</p><p>NHSC, state and other profession-specific programs can require a qualifying role, site, license and service period. Verify the award year, restrictions, overlapping obligations and clawback terms. Determine PSLF eligibility separately. For NHSC, site approval is central and qualifying loan repayment funds are exempt from federal income and employment taxes.</p><h4>How to apply it</h4><p>Validate role, license, approved service location, award year, eligible debt, duration, exit liability and tax impact. Model awarded funds alongside PSLF only after matching independent employer and payment rules.</p><div class=\"check\"><strong>Worked example</strong><p>A clinician has a potential NHSC site and 72 PSLF months. Verify the actual employer for PSLF and obtain the award terms before modeling service, award application and payoff together.</p></div>"}, {"id": "m36", "title": "36 Business owners and student loans Part 1 Income inputs", "html": "<h3>36 Business owners and student loans Part 1 Income inputs</h3><p><strong>What you’ll learn.</strong> Build a bridge from business revenue to repayment income.</p><p>Separate business revenue, expenses, net profit, salary, distributions and federal AGI. A bank deposit is not a tax return input by itself. Build a CPA-verified bridge from gross receipts to the borrower’s projected and filed AGI.</p><h4>How to apply it</h4><p>Use books and tax documentation to distinguish revenue and net profit, then map adjustments and household income. Mark projected and filed numbers separately. Ask a tax professional to confirm the borrower-level AGI input.</p><div class=\"check\"><strong>Worked example</strong><p>A sole proprietor reports $180,000 revenue and $80,000 expenses. $100,000 is a preliminary net profit figure. Confirm the return, applicable adjustments and household inputs before estimating IDR.</p></div>"}, {"id": "m37", "title": "37 Business owners and student loans Part 2 Entity and benefits", "html": "<h3>37 Business owners and student loans Part 2 Entity and benefits</h3><p><strong>What you’ll learn.</strong> Identify income from both wages and pass-through activity.</p><p>Compare entity scenarios with a CPA. A change from sole proprietor to S corporation can affect wages, pass-through income, retirement and compliance costs. Owner draws or distributions alone can misrepresent total taxable income. Factor in liquidity and the cost of entity administration before drawing a conclusion.</p><h4>How to apply it</h4><p>Compare the tax return, W-2 and K-1 when applicable. Consider contributions, business reserves and the cost of changing entities. Keep the entity choice grounded in the whole household and business plan.</p><div class=\"check\"><strong>Worked example</strong><p>A shareholder takes a $60,000 salary plus a distribution. Request the W-2 and applicable Schedule K-1. Do not model IDR using salary alone.</p></div>"}, {"id": "m38", "title": "38 Business owners and student loans Part 3 Variable income", "html": "<h3>38 Business owners and student loans Part 3 Variable income</h3><p><strong>What you’ll learn.</strong> Manage student loan payments with uneven business income.</p><p>Create low, base and high scenarios tied to plausible changes in business results. Record when a lower income can be documented for recalculation, when recertification occurs and what reserves can absorb a higher bill. Coordinate quarterly taxes and retirement contribution decisions with the appropriate professionals.</p><h4>How to apply it</h4><p>Build low, base and high AGI projections, use approved documentation for changes, and set recertification reminders. Put the projected payment range in the cash forecast. Coordinate tax reserves and owner liquidity.</p><div class=\"check\"><strong>Worked example</strong><p>A $500 monthly increase under the high scenario requires $6,000 of annual cash flow. Put that assumption into the household budget and set a review trigger when income changes.</p></div>"}, {"id": "m39", "title": "39 Verifying source quality", "html": "<h3>39 Verifying source quality</h3><p><strong>What you’ll learn.</strong> Create a source trail another advisor can audit.</p><p>Start with the federal statute or final regulation for the rule, current FSA guidance for implementation and account documents for borrower status. Use the IRS for tax guidance and the applicable lender guide for mortgage treatment. Treat calculators as estimates and screenshots as dated evidence. Record any unresolved differences.</p><h4>How to apply it</h4><p>Capture rule link, date, applicable provision, client-specific evidence and an unresolved question list. Compare the highest-quality source for each fact. Save the version used to build the case model.</p><div class=\"check\"><strong>Worked example</strong><p>The borrower’s servicer email conflicts with an old webinar handout. Check the current federal rule and obtain clarification about the borrower’s account before recommending action.</p></div>"}, {"id": "m40", "title": "40 Student debt in mortgage underwriting", "html": "<h3>40 Student debt in mortgage underwriting</h3><p><strong>What you’ll learn.</strong> Coordinate student debt documentation with a mortgage lender.</p><p>The qualifying mortgage payment can differ from the borrower’s actual bill. Fannie Mae’s guide permits using a verified $0 IDR payment in specified circumstances. Its guidance for deferment and forbearance differs. FHA, VA and other products can have different rules. Confirm the exact product and documentation with the lender before changing repayment or refinancing.</p><h4>How to apply it</h4><p>Get the exact product and required documentation before changing plans. Distinguish actual bill, credit-report data and the amount underwriting uses. Model debt-to-income changes with the lender’s input, preserving federal protections where possible.</p><div class=\"check\"><strong>Worked example</strong><p>A lender uses $600 monthly for a student loan despite a $0 bill. Ask which rule and status were applied. Request written confirmation of acceptable documentation.</p></div>"}, {"id": "m41", "title": "41 Tax tradeoffs in repayment planning", "html": "<h3>41 Tax tradeoffs in repayment planning</h3><p><strong>What you’ll learn.</strong> Compare total household cost across filing choices.</p><p>Compare household taxes plus loan payments for each viable filing scenario. Consider changes to credits, deductions, state taxes, both spouses’ loan payments and the timing of the change. Separately model possible tax on a future discharge. Coordinate filing decisions with the tax professional.</p><h4>How to apply it</h4><p>Calculate annual tax difference and annual changes in loan payments for both spouses. Incorporate verified credit and deduction differences. Evaluate timing and long-term forgiveness effects separately.</p><div class=\"check\"><strong>Worked example</strong><p>Separate filing lowers combined payments by $310 monthly and increases annual taxes by $2,400. The illustrative annual improvement is $1,320 before other effects.</p></div>"}, {"id": "m42", "title": "42 AGI and filing status calculations", "html": "<h3>42 AGI and filing status calculations</h3><p><strong>What you’ll learn.</strong> Use AGI for repayment and taxable income for brackets.</p><p>AGI and taxable income serve different purposes. Determine which AGI and dependents apply to the plan, including any spouse inputs. Tax brackets apply marginally to taxable income. RAP generally applies the relevant rate to applicable AGI, then applies the monthly dependent reduction and floor.</p><h4>How to apply it</h4><p>Bring AGI from the applicable documented inputs. Work through marginal rates for tax estimates and the plan’s distinct payment formula for loans. Verify dependent assumptions and spouse interactions.</p><div class=\"check\"><strong>Worked example</strong><p>A borrower has $75,000 AGI, one eligible RAP dependent and $60,000 taxable income. RAP at 7% is $387.50 monthly using applicable AGI. Estimate taxes separately using filing status and taxable-income brackets.</p></div>"}, {"id": "m43", "title": "43 Domicile, community property and Form 1098", "html": "<h3>43 Domicile, community property and Form 1098</h3><p><strong>What you’ll learn.</strong> Address separate filing and community-property records.</p><p>For married borrowers domiciled in a community-property state, separately filed federal returns can allocate community income under state and federal rules. Form 8958 reports allocations when applicable. Form 1098-E reports student loan interest, while Form 1098-T generally reports tuition information. Tax treatment and documentation for an IDR calculation require separate verification.</p><h4>How to apply it</h4><p>Confirm domicile and how the tax professional allocates community and separate income. Use Form 8958 when applicable. Check whether the repayment process accepts alternate documents, and distinguish 1098-E from 1098-T.</p><div class=\"check\"><strong>Worked example</strong><p>A Texas spouse earns $110,000 and the other $40,000. Do not assume the lower spouse’s separate federal AGI equals salary. Obtain the CPA’s figures and confirm the plan’s accepted supporting documents.</p></div>"}, {"id": "m44", "title": "44 How student loan tax treatment changed", "html": "<h3>44 How student loan tax treatment changed</h3><p><strong>What you’ll learn.</strong> Identify possible future tax when debt is discharged.</p><p>The temporary broad federal exclusion for many student loan discharges ran through 2025. Starting in 2026, assume a potential federal tax cost unless the discharge qualifies for a specific exclusion. PSLF and certain programs, including qualifying disability and death discharges, have specific federal treatment. Review state rules, discharge date and any Forms 1099-C with a tax professional.</p><h4>How to apply it</h4><p>Record expected discharge year and program, determine potential federal and state exclusions, and get tax professional input. Use multiple incremental tax estimates and avoid treating a future balance as certain.</p><div class=\"check\"><strong>Worked example</strong><p>If $40,000 is taxable and an illustrative blended incremental rate is 22%, model $8,800. A qualified tax professional should verify the exclusion and actual incremental tax.</p></div>"}, {"id": "m45", "title": "45 Recent tax law changes and Section 127", "html": "<h3>45 Recent tax law changes and Section 127</h3><p><strong>What you’ll learn.</strong> Review changes to Section 127 and deductions before modeling AGI.</p><p>The 2025 law made qualifying employer student loan assistance under Section 127 permanent. The 2026 federal exclusion generally covers up to $5,250 in combined qualifying educational assistance under a written program. Check later-year indexed amounts and plan terms. Screen tax changes individually and distinguish below-AGI deductions from adjustments that change AGI. The law’s qualified tips, qualified overtime, eligible vehicle loan interest and enhanced senior deductions are reported on Schedule 1-A and can reduce taxable income without reducing AGI used in an AGI-based loan estimate.</p><h4>How to apply it</h4><p>Verify written plan, qualifying loan, annual combined educational assistance, and payroll. Determine whether a claimed deduction is above or below AGI before altering an IDR estimate.</p><div class=\"check\"><strong>Worked example</strong><p>An employer pays $3,000 of qualifying tuition and $2,500 on qualifying loans in 2026. Compare the combined $5,500 with the $5,250 exclusion and confirm payroll treatment of the excess.</p></div>"}, {"id": "m46", "title": "46 Why legacy income driven plans still matter", "html": "<h3>46 Why legacy income driven plans still matter</h3><p><strong>What you’ll learn.</strong> Identify when a legacy plan can still help.</p><p>Eligible pre-cutoff borrowers may still have IBR, PAYE or ICR options based on loan history. A legacy plan can be attractive for monthly cash flow or forgiveness horizon, even if it will phase out. Include a dated successor plan before recommending a transition-period option.</p><h4>How to apply it</h4><p>Audit current eligibility, recent first disbursements and the projected transition date. Compare the near-term payment and time to qualifying discharge. Record a fallback if income or loan status changes.</p><div class=\"check\"><strong>Worked example</strong><p>A pre-cutoff borrower expects PSLF in 11 months. Compare current qualifying plan continuity and the actual retirement timeline before changing plans.</p></div>"}, {"id": "m47", "title": "47 Mapping options after REPAYE and SAVE", "html": "<h3>47 Mapping options after REPAYE and SAVE</h3><p><strong>What you’ll learn.</strong> Build a borrower-specific action plan after SAVE.</p><p>SAVE ended in March 2026. Verify the actual servicer notice for timing and pending application status. Build a list of currently eligible plans. Review whether paused months qualify, whether earlier plan status is restored after a pending application, and how the first bill will be set.</p><h4>How to apply it</h4><p>Find the notice, response deadline and current plan or pending application. Compare eligible options, select a confirmed action date, then watch the approval and first bill. Check the effect of forbearance months on count.</p><div class=\"check\"><strong>Worked example</strong><p>A borrower has 12 days to act. Confirm the notice deadline and eligibility today, then check that the request was received and the new bill matches the approved plan.</p></div>"}, {"id": "m48", "title": "48 PAYE eligibility and payment mechanics", "html": "<h3>48 PAYE eligibility and payment mechanics</h3><p><strong>What you’ll learn.</strong> Estimate payment and eligibility for legacy PAYE.</p><p>For eligible legacy borrowers, PAYE generally uses 10% of discretionary income, limited by the applicable 10-year Standard payment, with a typical 20-year horizon. Check its borrower-vintage requirements and current enrollment rules. Plan for retirement by July 1, 2028.</p><h4>How to apply it</h4><p>Verify cohort and loan vintage before running the 10% discretionary-income calculation and the Standard cap. Note the sunset and timed fallback. Review recent applications or disbursements.</p><div class=\"check\"><strong>Worked example</strong><p>$30,000 discretionary income produces $250 monthly before the cap. Verify whether the borrower’s history makes PAYE available and compare a successor plan.</p></div>"}, {"id": "m49", "title": "49 PAYE exit and the path back", "html": "<h3>49 PAYE exit and the path back</h3><p><strong>What you’ll learn.</strong> Check reentry before leaving PAYE.</p><p>Before switching, verify current enrollment rules and whether a later return would remain possible. New disbursements or consolidation after the cutoff can close access to legacy plans. PAYE retirement also ends access. Keep written evidence of the rule and the client’s decision. Separate theoretical availability from eligibility for this file on the expected date.</p><h4>How to apply it</h4><p>Write down the proposed exit date, any planned new disbursement, the final transition deadline and the rules for returning. Run a scenario with the alternative plan as permanent if reentry is uncertain.</p><div class=\"check\"><strong>Worked example</strong><p>A borrower wants to switch temporarily and then return to PAYE. Model the fallback assuming return is unavailable, and verify current access before any submission.</p></div>"}, {"id": "m50", "title": "50 Calculating ICR", "html": "<h3>50 Calculating ICR</h3><p><strong>What you’ll learn.</strong> Calculate the ICR payment using both methods.</p><p>ICR generally uses the lesser of 20% of discretionary income or a 12-year fixed repayment amount adjusted for income. It generally has a 25-year term. Its discretionary-income measure differs from IBR. Use the published adjustment calculation or official estimate and verify date and loan eligibility.</p><h4>How to apply it</h4><p>Use the correct ICR discretionary-income inputs and the published income-adjusted 12-year amount. Compare both estimates and select the lower. Exercise assumes eligibility under current rules.</p><div class=\"check\"><strong>Worked example</strong><p>If the two verified ICR calculations are $400 and $310, the modeled payment is $310. Confirm the transition timing before treating it as long term.</p></div>"}, {"id": "m51", "title": "51 ICR transition and Parent PLUS history", "html": "<h3>51 ICR transition and Parent PLUS history</h3><p><strong>What you’ll learn.</strong> Check the legacy Parent PLUS pathway before any new consolidation.</p><p>Parent PLUS is generally excluded from IDR without a qualifying legacy consolidation. Eligible Parent PLUS borrowers who consolidated before July 1, 2026, may be able to use ICR and, after at least one qualifying ICR payment in the July 4, 2025 to July 1, 2028 window under current instructions, request IBR. A consolidation containing Parent PLUS after the cutoff is generally outside IDR. The parent’s own employer and history determine any PSLF analysis.</p><ol class=\"steps\"><li>Trace Parent PLUS lineage</li><li>Verify pre-cutoff consolidation</li><li>Verify ICR payment and window</li><li>Confirm IBR and PSLF separately</li></ol><h4>How to apply it</h4><p>Verify parent ownership, Direct Consolidation first disbursement by June 30, 2026, and documented ICR payment history. Check FSA’s specified payment window and options for IBR. Confirm limits before mixing parent and student debt.</p><div class=\"check\"><strong>Worked example</strong><p>A May 2026 consolidation has one posted ICR payment. Verify lineage and IBR access. Reassess the entire file before changing the plan or consolidating again.</p></div>"}, {"id": "m52", "title": "52 Keeping PSLF on track through a plan change", "html": "<h3>52 Keeping PSLF on track through a plan change</h3><p><strong>What you’ll learn.</strong> Keep a PSLF case moving during a plan transition.</p><p>Confirm qualifying employment, signed forms, loan type, accepted counts and qualifying plan. Track any month between the last old-plan bill and first new-plan bill. Tiered Standard does not qualify. Review case-specific RAP timing and payment rules and the status of any periods of pause.</p><h4>How to apply it</h4><p>Check employer eligibility, certified counts and bill dates. Monitor intervening account status and reconcile count after the switch. Model why a low fixed payment could still cost the borrower if it stalls progress.</p><div class=\"check\"><strong>Worked example</strong><p>An eligible borrower is seven qualifying months from PSLF and has a pending plan change. Capture official counts and dates, verify treatment of intervening months and track new bills.</p></div>"}, {"id": "m53", "title": "53 Comparing transition plans", "html": "<h3>53 Comparing transition plans</h3><p><strong>What you’ll learn.</strong> Choose among repayment options using a decision record.</p><p>Create a matrix with available plan, estimated current payment, deadline, forgiveness count treatment, successor plan and trade-offs. Run both the near-term cash-flow impact and the longer forecast. For an eligible borrower, PAYE or ICR may bridge a period, RAP may offer balance protections, IBR may preserve legacy options, and a fixed plan may provide a clear payoff term.</p><h4>How to apply it</h4><p>Compare available plans through the client’s deadline and across a longer horizon. Specify what changes when legacy plans end. Add cash cost, interest treatment, time remaining and tax assumptions with a dated successor plan.</p><div class=\"check\"><strong>Worked example</strong><p>If PAYE is $260 today and RAP $310, compare cost through the expected switch date and afterward. Verify whether a pending new disbursement changes the table.</p></div>"}, {"id": "m54", "title": "54 Worked transition cases", "html": "<h3>54 Worked transition cases</h3><p><strong>What you’ll learn.</strong> Apply transition rules to real-world client trade-offs.</p><p><strong>Nurse:</strong> 96 PSLF payments, $90,000 eligible Direct, $95,000 applicable AGI and two RAP dependents. RAP at 9% is $612.50 before any spouse-debt adjustment. A flat payment over 24 qualifying months is $14,700. Model a job change separately.</p><p><strong>Parent:</strong> Legacy May 2026 consolidation includes Parent PLUS and has one ICR payment. Verify the legacy IBR path, deadline and official loan history.</p><p><strong>Returning student:</strong> Defaulted Direct loans and school starts in eight weeks. Compare rehabilitation and eligible consolidation, verify aid timing with school and holder, and account for credit impact.</p><h4>How to apply it</h4><p>Run a former SAVE nurse case, a legacy Parent PLUS case and a returning student in default. Each requires a different first document and decision deadline. Identify one constraint that could reverse each recommendation.</p><div class=\"check\"><strong>Worked example</strong><p>For each case name the next action, its owner, due date and the evidence required to proceed.</p></div>"}, {"id": "m55", "title": "55 Borrower eligibility decision", "html": "<h3>55 Borrower eligibility decision</h3><p><strong>What you’ll learn.</strong> Build the final eligibility and action record.</p><p>Apply the gates in order: identity and ownership, programs and lineage, first disbursement and cutoff dates, loan status, borrower cohort, employment and counts, applicable income details, notices and deadlines. Determine viable plans or escalation. Confirm the borrower’s choice and verify subsequent billing and counts.</p><h4>How to apply it</h4><p>Start with ownership and lineage, then dates, status and any default. Proceed to income, family, employer, counted months and notices. Record eligible plans, evidence gaps and next owner. Confirm borrower submission and the later official result.</p><div class=\"check\"><strong>Worked example</strong><p>A client has a post-cutoff Direct loan, older FFEL and a spouse’s Parent PLUS. Split the file by borrower and loan group, inspect each for eligibility, and leave assumptions visible for supervisor review.</p></div>"}, {"id": "START_HERE", "title": "Start here", "html": "<section class=\"card\"><h3>Learner materials</h3><ul><li>55-module learner manual</li><li>Student workbook and case files</li></ul></section><section class=\"card\"><h3>Teaching decks</h3><ul><li>Federal loan foundations</li><li>Income-driven repayment</li><li>Tax and financial advising</li><li>The 2026–2028 transition</li></ul></section><section class=\"card\"><h3>Assessment and instructor materials</h3><ul><li>100-question final exam</li><li>30-question applied retake</li><li>Instructor guide with keys, rubrics and renewal exercise</li></ul></section><section class=\"card\"><h3>Review and TAC setup</h3><p>Unzip the folder and open this page in a browser. No connection is needed except to open official reference links. For TAC setup, map each lesson by module number. Gate scored assessments and instructor keys by role. Use the answer table to configure scoring and record completion. Give learners only the appropriate files.</p><p>This original internal course follows the public topic sequence of the <a href=\"https://cslainstitute.org/program\">CSLA Institute’s 2026 curriculum</a>. The proposed internal award is TAC Academy Certificate in Student Loan Planning. The Institute administers its own CSLP® designation. Review dated procedures, credential language and assessment settings before publishing.</p></section>"}, {"id": "Student_Workbook", "title": "Student workbook", "html": "<p>Keep one copy per learner. Write your answers before the debrief. All cases are fictional. Use the blank models below and cite the dated source you rely on.</p><section class=\"card\"><h3>Loan inventory</h3><div class=\"wide\"><table><thead><tr><th scope=\"col\">Borrower &amp; loan</th><th scope=\"col\">Program &amp; holder</th><th scope=\"col\">First disbursement &amp; lineage</th><th scope=\"col\">Principal / interest / rate</th><th scope=\"col\">Plan, status &amp; bill</th><th scope=\"col\">Counts &amp; date</th><th scope=\"col\">Source</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table></div></section><section class=\"card\"><h3>Repayment comparison</h3><div class=\"wide\"><table><thead><tr><th scope=\"col\">Decision item</th><th scope=\"col\">Current path</th><th scope=\"col\">Alternative</th><th scope=\"col\">Downside scenario</th></tr></thead><tbody><tr><td>Eligibility and evidence</td><td></td><td></td><td></td></tr><tr><td>Monthly payment</td><td></td><td></td><td></td></tr><tr><td>Cash paid over the comparison period</td><td></td><td></td><td></td></tr><tr><td>Expected payoff or forgiveness date</td><td></td><td></td><td></td></tr><tr><td>Remaining balance and potential tax</td><td></td><td></td><td></td></tr><tr><td>What could change the outcome</td><td></td><td></td><td></td></tr></tbody></table></div></section><section class=\"card\"><h3>Follow-up record</h3><div class=\"wide\"><table><thead><tr><th scope=\"col\">Action</th><th scope=\"col\">Owner</th><th scope=\"col\">Due</th><th scope=\"col\">Confirmation evidence</th><th scope=\"col\">Next check</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table></div></section><section class=\"card\"><h3>Calculation reference</h3><div class=\"wide\"><table><thead><tr><th scope=\"col\">Calculation</th><th scope=\"col\">Method</th></tr></thead><tbody><tr><td>Simple daily interest</td><td>Principal × annual rate ÷ applicable day-count basis</td></tr><tr><td>Fixed installment</td><td>Principal × monthly rate ÷ [1 − (1 + monthly rate)⁻ᵐᵒⁿᵗʰˢ]. If the rate is zero, divide principal by months.</td></tr><tr><td>IBR illustration</td><td>Applicable discretionary income × cohort rate ÷ 12, subject to the cap</td></tr><tr><td>RAP illustration</td><td>Applicable bracket amount per month − $50 per eligible dependent, subject to the $10 minimum</td></tr><tr><td>Annual household cost</td><td>Annual tax + all household student loan payments for the selected filing scenario</td></tr></tbody></table></div></section><h2 id=\"section1\">Federal loan foundations knowledge check</h2><section class=\"card\"><h3>Question 1</h3><p>What two records would you reconcile before reporting the balance of a federal consolidation?</p><div class=\"answer-line\" aria-hidden=\"true\"></div></section><section class=\"card\"><h3>Question 2</h3><p>Show what happens to principal and interest when $900 of interest capitalizes onto $18,000 at 5%.</p><div class=\"answer-line\" aria-hidden=\"true\"></div></section><section class=\"card\"><h3>Question 3</h3><p>A borrower’s fixed repayment offer starts low but rises. What three pieces of evidence should go in the comparison?</p><div class=\"answer-line\" aria-hidden=\"true\"></div></section><section class=\"card\"><h3>Question 4</h3><p>Explain why a school’s aid offer and a federal aggregate cap can produce different numbers.</p><div class=\"answer-line\" aria-hidden=\"true\"></div></section><h2 id=\"section2\">Income-driven repayment knowledge check</h2><section class=\"card\"><h3>Question 1</h3><p>Calculate RAP at $82,000 AGI with two eligible dependents using 8%.</p><div class=\"answer-line\" aria-hidden=\"true\"></div></section><section class=\"card\"><h3>Question 2</h3><p>For the same loan, 215 months have been confirmed eligible for a 240-month plan and a 360-month plan. How many months remain under each?</p><div class=\"answer-line\" aria-hidden=\"true\"></div></section><section class=\"card\"><h3>Question 3</h3><p>List eligibility evidence you would want before submitting a PSLF buyback request with 118 certified payments.</p><div class=\"answer-line\" aria-hidden=\"true\"></div></section><section class=\"card\"><h3>Question 4</h3><p>A borrower has variable commissions. What two sensitivities would you show when comparing eligible RAP and IBR?</p><div class=\"answer-line\" aria-hidden=\"true\"></div></section><h2 id=\"section3\">Tax and financial advising knowledge check</h2><section class=\"card\"><h3>Question 1</h3><p>A household saves $4,800 annually on student loan payments by filing separately, but owes $5,100 more in tax. What is the first-pass household effect?</p><div class=\"answer-line\" aria-hidden=\"true\"></div></section><section class=\"card\"><h3>Question 2</h3><p>Differentiate a $0 IDR payment from a forbearance in the lender conversation.</p><div class=\"answer-line\" aria-hidden=\"true\"></div></section><section class=\"card\"><h3>Question 3</h3><p>An employer pays $4,200 in tuition and $1,200 toward eligible loans under its written plan in 2026. How far over the general Section 127 cap is it?</p><div class=\"answer-line\" aria-hidden=\"true\"></div></section><section class=\"card\"><h3>Question 4</h3><p>Name three pieces of paper or approved records you would assemble for a business-owner IDR file.</p><div class=\"answer-line\" aria-hidden=\"true\"></div></section><h2 id=\"section4\">The 2026–2028 transition knowledge check</h2><section class=\"card\"><h3>Question 1</h3><p>What three dates or date ranges should a former SAVE borrower with legacy loans check before choosing a plan?</p><div class=\"answer-line\" aria-hidden=\"true\"></div></section><section class=\"card\"><h3>Question 2</h3><p>A borrower’s Direct Consolidation including Parent PLUS was disbursed May 30, 2026. What qualifying event should be investigated before proposing IBR?</p><div class=\"answer-line\" aria-hidden=\"true\"></div></section><section class=\"card\"><h3>Question 3</h3><p>An approved ICR estimate compares $365 and $525 under the two methods. State the estimate and the plan timing caveat.</p><div class=\"answer-line\" aria-hidden=\"true\"></div></section><section class=\"card\"><h3>Question 4</h3><p>What three confirmations should an agent record after a borrower submits a plan selection?</p><div class=\"answer-line\" aria-hidden=\"true\"></div></section><h2>Practice cases</h2><section class=\"card\"><h3>Case 1 · Jordan’s SAVE deadline and PSLF case</h3><p>Jordan’s $90,000 in legacy Direct Loans has 96 qualifying payments. The SAVE notice gives 21 days to select a new plan. Use $95,000 household AGI and two eligible claimed dependents. Jordan has $20,000 private debt at 9% variable, a mortgage application in four months, and a possible move to a nonqualifying employer. The spouse may have qualifying federal debt.</p><p>Calculate an initial RAP estimate, name an eligible alternative to investigate, and explain the job change and mortgage trade-offs. Give the next three actions with owners and dates.</p><div class=\"answer-line\" aria-hidden=\"true\"></div></section><section class=\"card\"><h3>Case 2 · Elena’s Parent PLUS decision</h3><p>Elena works at a nonprofit. Her own $8,000 Direct Unsubsidized Loan is separate from a $40,000 Direct Consolidation that repaid a Parent PLUS loan. The consolidation first disbursed June 12, 2026. Her July 2026 bill says ICR, and August transaction history shows a posted payment. Her adult child makes payments voluntarily.</p><p>Identify the legal borrower, eligibility evidence and next actions. Explain what to verify before combining her loan groups.</p><div class=\"answer-line\" aria-hidden=\"true\"></div></section><section class=\"card\"><h3>Case 3 · Rafael’s return to school and default</h3><p>Rafael has defaulted Direct Loans and starts a program in eight weeks. A holder statement shows $19,000 principal and $1,600 accrued interest. He wants aid disbursed on time and the record of default removed if possible.</p><p>Compare rehabilitation and eligible consolidation. Name who verifies eligibility and the school deadline. Explain what happens to accrued interest and credit reporting.</p><div class=\"answer-line\" aria-hidden=\"true\"></div></section><section class=\"card\"><h3>Case 4 · Taylor and Morgan’s Texas tax comparison</h3><p>The CPA projects joint tax of $20,400 and total MFS tax of $24,000. Loan payments total $900 jointly and $530 separately under verified exercise assumptions. A home closing is pending. A draft individual AGI was based on wages alone.</p><p>Compute direct annual cost under both filings, identify which documents control the AGI inputs, and describe the next action before any change.</p><div class=\"answer-line\" aria-hidden=\"true\"></div></section><section class=\"card\"><h3>Case 5 · Avery’s business owner cash flow</h3><p>Avery’s business forecasts low, base and high AGI of $48,000, $68,000 and $88,000. Assume one eligible RAP dependent, no spouse adjustment and eligible Direct loans. Use 4%, 6% and 8%. Avery wants to contribute to retirement without draining reserves.</p><p>Compute all three RAP estimates, give the annual difference between base and high, and name the evidence that could trigger a recalculation.</p><div class=\"answer-line\" aria-hidden=\"true\"></div></section><section class=\"card\"><h3>Capstone hand-in checklist</h3><ol class=\"steps\"><li>Verified inventory</li><li>Two paths</li><li>Downside case</li><li>Three-minute briefing</li><li>Action log</li></ol><p>Use Jordan’s case. Explain what is known, what could change, and which decision is due first. Identify each person responsible for a follow-up step.</p></section>"}, {"id": "Retake_30_Applied_Questions", "title": "Applied retake workbook", "html": "<p>Use this supervised written form after targeted remediation. Give the relevant calculation, evidence or procedural explanation. Suggested pass is 24 out of 30.</p><section class=\"card\"><h3>Question 1</h3><p>The export shows $23,500 on a current consolidation, $0 on two predecessor loans and $6,400 on an active Direct loan. Give the current federal total and explain the zero-balance entries.</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 2</h3><p>Under assumed new federal professional limits, a student has $194,000 counted against the $205,000 aggregate cap and a $50,000 annual cap. How much aggregate capacity remains and who determines the actual award?</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 3</h3><p>Using a 365-day exercise basis, estimate 20 days of interest on $18,250 at 8%.</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 4</h3><p>List four contractual terms to request before comparing a variable-rate private quote to the current loan.</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 5</h3><p>Calculate the rate on $40,000 at 4.5% plus $10,000 at 6%, then round up to the nearest one-eighth percentage point for the example.</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 6</h3><p>A $750 capitalization event occurs on a $15,000 principal at 6%. What are the new principal and annual incremental interest at the static balance?</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 7</h3><p>A borrower sees a $0 bill during a pause. Give three facts to verify before calling the pause harmless.</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 8</h3><p>A graduated payment rises from $300 to $470 while monthly available cash stays $400. Give the shortfall and your next step.</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 9</h3><p>What tier applies at $24,999 and at $25,000 under the general Tiered Standard table? What should a PSLF borrower know about the plan?</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 10</h3><p>A student has a defaulted legacy FFEL loan and an aid deadline. Which parties verify default resolution and disbursement timing?</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 11</h3><p>A client has 120 certified employment months and 118 payments. Give two additional facts to establish before applying for PSLF buyback.</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 12</h3><p>A relative who is supported by the borrower is absent from the federal tax return. Explain the effect on RAP and IBR modeling.</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 13</h3><p>Assuming 10% IBR, AGI of $77,000, a poverty allowance of $35,000, and a cap of $330, give the uncapped and capped estimates.</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 14</h3><p>Assume $39,600 discretionary income and a $470 cap under legacy 15% IBR. Give the billed estimate and usual term.</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 15</h3><p>At $72,000 AGI and three eligible dependents, use the 7% RAP rate and give the modeled payment.</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 16</h3><p>A borrower has 222 verified months eligible under both a 240-month IBR and a 360-month RAP target. How many remain in each?</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 17</h3><p>A borrower claims autopay withdrew on time but the servicer shows a late posting. What records and action do you request?</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 18</h3><p>Name four TAC intake fields needed when a borrower has a SAVE notice.</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 19</h3><p>Write a follow-up entry for an IDR request already submitted by the borrower.</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 20</h3><p>Write one sentence an advisor can use when the borrower offers to share a password.</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 21</h3><p>A clinician is deciding between a service award and an employer likely to qualify for PSLF. Name four checks before comparing compensation.</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 22</h3><p>Your high AGI scenario costs $855 monthly and the base costs $455. Give the annual increase and one monitoring trigger.</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 23</h3><p>A lender says a paused account is different from actual $0 IDR. What do you send or verify?</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 24</h3><p>Separate filing saves the household $415 a month on loans and increases tax by $5,400 annually. What is the direct difference?</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 25</h3><p>What is Form 8958 used for, and why should the agent still verify the IDR income input?</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 26</h3><p>A $36,000 projected taxable discharge uses an illustrative 20% incremental rate. Give the reserve and two unresolved inputs.</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 27</h3><p>A former SAVE borrower has a notice due in 10 days with a pending application. Give three steps in order.</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 28</h3><p>A PAYE borrower wants a new Direct Consolidation loan and expects to reenter PAYE afterward. How do you review the assumption?</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 29</h3><p>A June 2026 qualifying Parent PLUS consolidation has no ICR payment showing. Name evidence and timing to verify.</p><div class=\"answer-line\"></div></section><section class=\"card\"><h3>Question 30</h3><p>A borrower’s loan is now on Tiered Standard with 112 existing PSLF months. What do you explain and do next?</p><div class=\"answer-line\"></div></section>"}, {"id": "Section_1_Teaching_Deck", "title": "Section 1 teaching deck", "html": "<div class=\"slide-controls hide-print\"><button id=\"prev\" type=\"button\">Previous</button><button id=\"next\" type=\"button\">Next</button><span id=\"counter\" aria-live=\"polite\"></span><label><input type=\"checkbox\" id=\"toggle\"> Show speaker notes</label></div><article class=\"slide\"><div class=\"tag\">Section 1</div><h2>Federal loan foundations</h2><section class=\"figure\"><h3>From loan records to a plan</h3><ol class=\"steps\"><li>Identify the borrower</li><li>Trace loan history</li><li>Verify balance and status</li><li>Compare eligible options</li></ol><div class=\"wide\"><table><thead><tr><th scope=\"col\">Example record</th><th scope=\"col\">Current balance</th><th scope=\"col\">Inventory treatment</th></tr></thead><tbody><tr><td>Closed predecessor</td><td> $0</td><td>Keep as history</td></tr><tr><td>Active consolidation</td><td>$19,200</td><td>Count once</td></tr><tr><td>Other active Direct loan</td><td>$3,600</td><td>Add to active total</td></tr></tbody></table></div></section><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Put the loan inventory on screen. Ask learners to point to the legal borrower, current balance and oldest document. Have them explain why a closed record can stay in the history.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 01</div><h2>Downloading and reading NSLDS records</h2><p>Reconcile a federal export to a working loan inventory.</p><div class=\"callout\"><p>National Student Loan Data System records are visible through the borrower’s StudentAid.gov account.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>National Student Loan Data System records are visible through the borrower’s StudentAid.gov account. Have the borrower sign in privately, open My Aid and use the data-download option. Read loan type, first disbursement date, original amount, current balance, holder and status history. Reconcile current payments and accrued interest against statements. Use official PSLF records for counts. Keep a dated original and a redacted working inventory in approved storage.</p><p>Start with a borrower-controlled download. Identify original loan IDs, then mark active, paid through consolidation, and otherwise closed rows. Compare the remaining accounts to a statement dated as close as possible to the export. Confirm suspected transfers with the servicer.</p><p><strong>Debrief.</strong> An old loan shows zero and a consolidation shows $32,000. Before totaling the file, trace whether consolidation paid off the old loan. Capture both as history, with the outstanding balance attributed once.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 02</div><h2>Federal student loan programs</h2><p>Classify loans before choosing a relief program.</p><div class=\"callout\"><p>Direct Subsidized loans are for eligible undergraduates with financial need.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Direct Subsidized loans are for eligible undergraduates with financial need. Direct Unsubsidized loans accrue interest during school and can serve eligible undergraduate and graduate borrowers. Parent PLUS belongs to the signing parent. Grad PLUS belongs to the graduate borrower and is being phased out for new borrowers subject to exceptions. FFEL and Perkins are legacy federal programs with different holders and access to federal benefits.</p><p>Group records by legal borrower first, then source program and current holder. Resolve any school-originated account using the note and school records. A private lender can service a legacy federal loan, so the lender name alone is insufficient.</p><p><strong>Debrief.</strong> A nurse holds Direct, Perkins and private debt. PSLF is a Direct Loan program. Check Perkins cancellation before proposing consolidation and keep private debt separate.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 03</div><h2>Federal borrowing limits and eligibility</h2><p>Distinguish a program cap from the borrower’s actual award.</p><div class=\"callout\"><p>Distinguish annual limits, aggregate limits, remaining eligibility and the school’s actual award.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Distinguish annual limits, aggregate limits, remaining eligibility and the school’s actual award. Undergraduate limits vary by year and dependency status. For borrowers subject to the new rules, general graduate caps are $20,500 annually and $100,000 aggregate, professional caps $50,000 and $205,000, and Parent PLUS caps $20,000 per year and $65,000 aggregate per dependent student. Check exception status, enrollment intensity, prior borrowing and classification with the school.</p><p>Check program classification, exception status, dependency, attendance level, prior borrowing, net cost and other aid. Apply annual and aggregate limits separately. Get a dated confirmation from the school before telling a family how much they can borrow.</p><p><strong>Debrief.</strong> A program calls itself professional in its brochure. The financial aid office must confirm how it is classified under federal rules before you model the higher cap.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 04</div><h2>Interest rates on federal loans</h2><p>Calculate loan interest and pick the right rate vintage.</p><div class=\"callout\"><p>Use first disbursement date and loan type to select the rate.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Use first disbursement date and loan type to select the rate. For July 1, 2026 through June 30, 2027, fixed rates are 6.52% for undergraduate Direct Subsidized and Unsubsidized, 8.07% for graduate or professional Direct Unsubsidized, and 9.07% for Direct PLUS. Origination fees can reduce the amount delivered while the borrower owes the gross loan principal.</p><p>Match the rate to the first disbursement and loan type. Convert the annual rate to a decimal and multiply it by principal and elapsed days divided by the applicable day-count basis. Compare the resulting accrual with the servicer history.</p><p><strong>Debrief.</strong> $20,000 at 6.52% accrues about $3.57 daily using 365.25 days. Use the servicer’s posting and day basis for a live payoff.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 05</div><h2>Applying for federal aid and loans</h2><p>Walk a student from FAFSA to a documented disbursement.</p><div class=\"callout\"><p>The borrower completes FAFSA, reviews the aid offer with the school, accepts only what is needed, and completes any required entrance counseling and Master Promissory Note.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>The borrower completes FAFSA, reviews the aid offer with the school, accepts only what is needed, and completes any required entrance counseling and Master Promissory Note. Determine whether a Parent PLUS or eligible legacy Grad PLUS application has additional steps. Confirm school deadlines, disbursement schedule and whether an existing default requires resolution.</p><p>Confirm which academic year is needed. List grants and scholarships first, estimate uncovered cost, then compare available federal loans, fees and timing. Check the aid offer, acceptance, counseling and signed note. The school confirms disbursement.</p><p><strong>Debrief.</strong> A student needs $8,000 after grants and is offered $12,000. Confirm the budget, expected fees and school rules before accepting the necessary amount.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 06</div><h2>Private and other nonfederal loans</h2><p>Compare private debt terms with borrower cash flow.</p><div class=\"callout\"><p>Read the promissory note and current statement for rate type, index and margin, term, cosigner release, hardship options and discharge terms.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Read the promissory note and current statement for rate type, index and margin, term, cosigner release, hardship options and discharge terms. State or institutional loans may have distinct terms. Private contracts generally do not provide federal IDR or PSLF. Compare offers by APR, term, payment, total cost and protections.</p><p>Collect the current statement and note. Verify index, margin, reset frequency, cap, cosigner terms and hardship policy. Calculate base and adverse cash flow, and compare any refinance quote at the same repayment term.</p><p><strong>Debrief.</strong> A variable-rate borrower owes $25,000. A two-point rate increase adds roughly $500 in annual interest at that balance before amortization.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 07</div><h2>Comparing federal consolidation and private refinancing</h2><p>Explain consolidation and private refinancing in client language.</p><div class=\"callout\"><p>Direct Consolidation pays off included federal loans with a new federal loan.</p></div><div class=\"wide\"><table><thead><tr><th scope=\"col\">Choice</th><th scope=\"col\">What changes</th></tr></thead><tbody><tr><td>Keep current loans</td><td>Preserves the current products, subject to existing rules.</td></tr><tr><td>Direct Consolidation</td><td>Creates a new federal loan. Verify rates, eligible plans, and counts.</td></tr><tr><td>Private refinance</td><td>Creates private debt. Federal protections on included balances generally end.</td></tr></tbody></table></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Direct Consolidation pays off included federal loans with a new federal loan. Its weighted rate generally rounds up to the next eighth of a percentage point. It can change repayment eligibility, cost, payment counts and other benefits. Private refinancing pays off included debt with a private loan. Refinancing federal loans privately generally forfeits federal protections on those loans.</p><p>Show the included loans, new product, weighted rate, principal after capitalization and repayment history. Compare forgiveness, hardship and discharge effects before approval. Use a written before-and-after table for federal debt going into a private quote.</p><p><strong>Debrief.</strong> $30,000 at 5% and $20,000 at 7% produce 5.8% weighted, rounded up to 5.875%. Model keeping the loans separate before acting.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 08</div><h2>When accrued interest becomes principal</h2><p>Distinguish interest accrual from capitalization.</p><div class=\"callout\"><p>Unpaid interest and principal are separate until a capitalization event adds interest to principal.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Unpaid interest and principal are separate until a capitalization event adds interest to principal. Future interest then accrues on the larger base. Verify the trigger for the loan and the current rule. Forbearance may result in interest accrual even when capitalization does not occur immediately.</p><p>Use current principal and accrued interest as separate inputs. Look for a documented capitalization event and reconcile the next statement. Do not add unpaid interest to principal automatically in your model.</p><p><strong>Debrief.</strong> If $2,000 capitalizes on $40,000 at 6%, annual simple interest rises by $120 at the new principal. Confirm whether the $2,000 actually capitalized before modeling.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 09</div><h2>Weighted averages and payment allocation</h2><p>Distinguish amount owed, payment posting and blended rates.</p><div class=\"callout\"><p>Distinguish the weighted consolidation rate, weighted forgiveness count and the servicer’s allocation of a payment across loan groups.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Distinguish the weighted consolidation rate, weighted forgiveness count and the servicer’s allocation of a payment across loan groups. A $400 payment allocated strictly in proportion to $15,000 and $5,000 balances would be $300 and $100. The servicer can use different allocation rules and loan-level charges. Check instructions for extra payments, amounts past due and whether the next bill advances.</p><p>First satisfy amounts due across groups. Then ask which group receives any extra, when the servicer advances the due date, and how fees and interest are applied. Verify the posting from transaction history.</p><p><strong>Debrief.</strong> Before targeting a high-rate loan, confirm the required payment on all groups, provide permitted borrower instructions, and check the actual posting.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 10</div><h2>Grace periods and payment pauses</h2><p>Assess the cost and consequences of a temporary payment pause.</p><div class=\"callout\"><p>A grace period follows specified enrollment changes for eligible loans.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>A grace period follows specified enrollment changes for eligible loans. Deferment depends on a qualifying condition. Forbearance pauses or reduces scheduled payments under applicable rules. Interest treatment, count credit and expiration vary by program and status. Identify the specific effective dates and first bill.</p><p>Identify pause type, eligible period, interest treatment and whether particular months can count. List the end date and first bill. Compare pause, recertification and another available plan when the borrower’s income drops.</p><p><strong>Debrief.</strong> A pause lasts four months on $30,000 at 6%. Approximate accrued interest is $600 if all interest accrues to the borrower and principal stays flat. Ask whether any month counts toward forgiveness.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 11</div><h2>How income-driven repayment evolved</h2><p>Translate a historical plan name into a current decision.</p><div class=\"callout\"><p>IDR bases payments on income and plan-specific household inputs.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>IDR bases payments on income and plan-specific household inputs. Older programs included ICR, IBR, PAYE and REPAYE. SAVE replaced REPAYE and was ended by court order in March 2026. RAP became available in July 2026. An account may show historical plan names. Use the history to investigate credits and current rules to verify today’s choices.</p><p>Build a plan timeline including entry and exit dates and repayment status. Match each historical plan to the applicable rule then check today’s eligible options. Ask whether billing and payment counts moved after the transition.</p><p><strong>Debrief.</strong> A 2024 statement says SAVE. Record it as historical evidence and retrieve the current plan and transition notice.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 12</div><h2>Graduated fixed repayment</h2><p>Evaluate a graduated payment schedule.</p><div class=\"callout\"><p>A graduated schedule starts lower and generally steps up every two years.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>A graduated schedule starts lower and generally steps up every two years. Review plan eligibility and the actual step schedule. Compared with level repayment, lower early principal reduction can increase lifetime interest. Test future payments against a realistic earnings path.</p><p>Request the actual schedule and compare every step with a flat-income budget. Sum the scheduled payments over the applicable term and stress-test planned income increases. Confirm any PSLF eligibility independently.</p><p><strong>Debrief.</strong> A client can handle $350 today but the quote reaches $650. Ask how they would handle the step-up if income stayed flat.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 13</div><h2>Extended level repayment</h2><p>Quantify the trade-off in extended level repayment.</p><div class=\"callout\"><p>Legacy federal Extended repayment can stretch eligible repayment to up to 25 years.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Legacy federal Extended repayment can stretch eligible repayment to up to 25 years. Its eligibility typically requires more than $30,000 in outstanding loans within the applicable program and other conditions. Compare with Standard and eligible IDR. A longer term can buy near-term affordability while raising total cost.</p><p>Verify program-level balance and plan eligibility, then compare level payments and lifetime interest at the same rate. Add an optional extra-payment scenario if the client wants lower required payments with flexibility.</p><p><strong>Debrief.</strong> $40,000 at 6% is about $444 monthly over 10 years versus $258 over 25 years using level-payment math. Total modeled payments are roughly $53,300 and $77,300.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 14</div><h2>Extended repayment with graduated payments</h2><p>Evaluate extended graduated payments against a flat alternative.</p><div class=\"callout\"><p>The extended graduated option combines a longer eligible term with rising payments over several repayment steps.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>The extended graduated option combines a longer eligible term with rising payments over several repayment steps. Request the full amortization schedule, calculate total dollars, and stress-test each increase. Compare that schedule with extended fixed repayment and eligible income-based choices.</p><p>Collect the starting, step-up and highest payments for the full term. Compare total payments and the dates on which the schedule would strain cash flow. Include a path for reassessment before the next increase.</p><p><strong>Debrief.</strong> The starting bill is $260 and the highest is $620. Separate the cash-flow improvement today from the future income needed to sustain it.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 15</div><h2>Tiered Standard repayment</h2><p>Map eligible balances to a Tiered Standard term.</p><div class=\"callout\"><p>The post-cutoff fixed plan uses a term based on the applicable Direct Loan balance.</p></div><div class=\"wide\"><table><thead><tr><th scope=\"col\">Applicable principal</th><th scope=\"col\">General maximum term</th></tr></thead><tbody><tr><td>Under $25,000</td><td>10 years</td></tr><tr><td>$25,000 to under $50,000</td><td>15 years</td></tr><tr><td>$50,000 to under $100,000</td><td>20 years</td></tr><tr><td>$100,000 and above</td><td>25 years</td></tr></tbody></table></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>The post-cutoff fixed plan uses a term based on the applicable Direct Loan balance. General terms are 10 years below $25,000, 15 years from $25,000 to below $50,000, 20 years from $50,000 to below $100,000, and 25 years from $100,000. Confirm the balance definition and eligibility. Tiered Standard payments do not qualify for PSLF.</p><p>Identify which Direct loans determine the applicable balance, then confirm whether the borrower falls under the post-cutoff fixed framework. Compare that term with eligible RAP and check PSLF consequences separately.</p><p><strong>Debrief.</strong> A qualifying borrower has $55,000 entering repayment. Model the 20-year tier and compare RAP if eligible.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 16</div><h2>Who does what in student loan servicing</h2><p>Route a billing or eligibility problem to the right party.</p><div class=\"callout\"><p>The federal dashboard provides program records.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>The federal dashboard provides program records. The servicer handles bills and processing. A defaulted account may be handled by the Default Resolution Group or a guaranty agency. The school confirms aid eligibility and disbursement. Route discrepancies first to the responsible party, then to the relevant FSA feedback or ombudsman channel if unresolved.</p><p>Use servicers for billing and posting, FSA for federal program tracking, the school for aid, and the holder, DRG or guaranty agency for default as applicable. Preserve receipts, names and case numbers. Escalate unresolved errors through the appropriate official channel.</p><p><strong>Debrief.</strong> A correct federal balance appears alongside a misapplied payment. Keep the receipt and transaction history, request correction from the servicer and log its case number.</p></aside></article><article class=\"slide\"><div class=\"tag\">Section 1 review</div><h2>Practice and discussion</h2><ol><li>What two records would you reconcile before reporting the balance of a federal consolidation?</li><li>Show what happens to principal and interest when $900 of interest capitalizes onto $18,000 at 5%.</li><li>A borrower’s fixed repayment offer starts low but rises. What three pieces of evidence should go in the comparison?</li><li>Explain why a school’s aid offer and a federal aggregate cap can produce different numbers.</li></ol><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Use My Aid or the federal export for loan history and the current servicer statement for the dated balance and billing.</p><p>Principal becomes $18,900. The increase in projected annual simple interest at a static balance is $45.</p><p>The full payment schedule, the applicable term and total paid, and realistic household cash flow at each step.</p><p>The cap is an upper bound. Enrollment, prior borrowing, cost, other aid, dependency, classification and exceptions can affect the actual award.</p></aside></article>"}, {"id": "Section_2_Teaching_Deck", "title": "Section 2 teaching deck", "html": "<div class=\"slide-controls hide-print\"><button id=\"prev\" type=\"button\">Previous</button><button id=\"next\" type=\"button\">Next</button><span id=\"counter\" aria-live=\"polite\"></span><label><input type=\"checkbox\" id=\"toggle\"> Show speaker notes</label></div><article class=\"slide\"><div class=\"tag\">Section 2</div><h2>Income-driven repayment</h2><section class=\"figure\"><h3>How one borrower’s monthly estimates compare</h3><p>Illustration for $75,000 applicable AGI, two eligible RAP dependents, and a $36,000 IBR poverty allowance. Assumes eligibility and no binding IBR cap.</p><div class=\"bar\"><span>10% IBR</span><i aria-hidden=\"true\" style=\"--width:96.3%\"></i><b>$325.00</b></div><div class=\"bar\"><span>RAP</span><i aria-hidden=\"true\" style=\"--width:100%\"></i><b>$337.50</b></div><div class=\"wide\"><table><thead><tr><th scope=\"col\">Plan</th><th scope=\"col\">Teaching calculation</th></tr></thead><tbody><tr><td>IBR</td><td>($75,000 − $36,000) × 10% ÷ 12</td></tr><tr><td>RAP</td><td>($75,000 × 7% ÷ 12) − $100</td></tr></tbody></table></div></section><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Lead with the same borrower under IBR and RAP. Compare eligibility first, then the projected result. Ask what facts would change the preferred option.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 17</div><h2>Auditing eligibility for PSLF buyback</h2><p>Determine when a PSLF buyback request is worth pursuing.</p><div class=\"callout\"><p>Map and certify employment by month using the PSLF Help Tool.</p></div><ol class=\"steps\"><li>120 certified employment months</li><li>Eligible months on current Direct loan</li><li>Buyback would complete PSLF</li><li>Follow the agreement</li></ol><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Map and certify employment by month using the PSLF Help Tool. Buyback applies to certain otherwise excluded deferment or forbearance months on eligible outstanding Direct loans when there are already 120 qualifying employment months and the purchase would result in forgiveness. Check disbursement and consolidation history. If FSA issues an agreement, follow its payment deadline and preserve proof.</p><p>Audit certified employment by month and identify eligible deferment or forbearance months on the outstanding Direct loan. Verify the current plan during those months, consolidation history and whether buyback achieves discharge. Compare with ordinary qualifying payments.</p><p><strong>Debrief.</strong> At 116 qualifying payments and 120 approved employment months, audit four uncovered months. Months on loans before the current consolidation cannot be bought back on that new loan.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 18</div><h2>Household size and dependents across plans</h2><p>Use the correct household inputs for each plan.</p><div class=\"callout\"><p>IBR uses plan-defined family size with an applicable poverty guideline.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>IBR uses plan-defined family size with an applicable poverty guideline. RAP uses a dollar reduction per eligible dependent claimed on a federal return. Filing status, spouse income, spouse debt and dependent rules can differ. Build a dated input record for each plan instead of carrying one headcount across both calculations.</p><p>Create separate rows for plan-based family size, return-claimed dependents, filing status and applicable spouse income and eligible debt. Ask who claimed each dependent and confirm any separate-filing or joint calculation rules. Save dated evidence.</p><p><strong>Debrief.</strong> A client supports a relative who is not claimed on the tax return. Verify IBR treatment independently and omit the RAP deduction unless federal eligibility is established.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 19</div><h2>Choosing between RAP and IBR</h2><p>Decide between IBR and RAP using the whole repayment path.</p><div class=\"callout\"><p>Compare payment now, annual recertification risk, interest treatment, projected balance and time to forgiveness.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Compare payment now, annual recertification risk, interest treatment, projected balance and time to forgiveness. RAP offers a rules-based interest waiver and principal contribution for qualifying payments. IBR can have a shorter forgiveness term and a cap tied to the 10-year Standard calculation. Use loan type and dates to establish that both are available.</p><p>Compare payment, interest and principal behavior, credited months, income changes and estimated payoff or forgiveness. Run probabilities or discrete downside scenarios without treating forgiveness as guaranteed. Use a common cash horizon before comparing totals.</p><p><strong>Debrief.</strong> At $75,000 AGI and two qualifying RAP dependents, 7% yields $337.50 monthly. If verified IBR is $325, compare official counts, the remaining term and cash cost before choosing.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 20</div><h2>How RAP fits into the IDR timeline</h2><p>Connect historical repayment changes to an individual loan timeline.</p><div class=\"callout\"><p>Build milestones by borrower cohort.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Build milestones by borrower cohort. Record the end of SAVE in March 2026, the July 2026 rollout of RAP and Tiered Standard, and retirement of legacy PAYE and ICR no later than July 1, 2028. Some legacy options remain available for eligible pre-cutoff borrowers. New loans and consolidations can change the available set.</p><p>Use three separate milestones for end of SAVE, July 2026 eligibility changes and July 2028 legacy sunset. Date any proposed consolidation or new first disbursement. Record whether it changes the borrower’s choices before proceeding.</p><p><strong>Debrief.</strong> A borrower expects to enroll in school next year. Add the potential new first disbursement to the model and reassess plan access before committing to an enrollment-dependent strategy.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 21</div><h2>Reviewing the one-time account adjustment</h2><p>Audit existing IDR adjustment credit.</p><div class=\"callout\"><p>The past IDR account adjustment credited certain months under special rules.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>The past IDR account adjustment credited certain months under special rules. Treat it as historical account evidence. Compare FSA’s count with repayment, deferment, forbearance and consolidation records. Identify unexplained gaps, then use the official dispute or feedback route with documentary evidence.</p><p>Compare the account’s adjusted count with loan-level statuses and servicing history. Flag missing months with dates and evidence. Handle any potential corrections through the official channel and retain the response.</p><p><strong>Debrief.</strong> Online history suggests 108 months while the borrower recalls 120. Build a month-by-month ledger rather than treating the twelve-month gap as automatically eligible.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 22</div><h2>The 10 percent IBR formula</h2><p>Calculate capped 10 percent IBR.</p><div class=\"callout\"><p>Determine borrower vintage using actual disbursements and outstanding history.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Determine borrower vintage using actual disbursements and outstanding history. If the borrower qualifies, estimate 10% of annual discretionary income divided by 12, subject to the applicable 10-year Standard cap. The typical forgiveness horizon is 20 years of qualifying payments. Discretionary income generally subtracts 150% of the applicable poverty guideline.</p><p>Confirm the newer IBR cohort and usable AGI, subtract the applicable poverty allowance, apply 10%, divide by twelve and check the cap. Save the source of each input.</p><p><strong>Debrief.</strong> AGI $72,000 less a hypothetical $32,000 allowance gives $333.33 before a cap. If the verified cap is $300, the modeled amount is $300.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 23</div><h2>The 15 percent legacy IBR formula</h2><p>Calculate capped legacy 15 percent IBR.</p><div class=\"callout\"><p>For the legacy IBR cohort, generally model 15% of discretionary income, subject to the applicable cap, and a 25-year qualifying payment term.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>For the legacy IBR cohort, generally model 15% of discretionary income, subject to the applicable cap, and a 25-year qualifying payment term. Identify whether FFEL or Direct debt is involved and verify loan-plan fit. The same income can produce a very different payment in the two IBR cohorts.</p><p>Confirm the legacy cohort, actual program and cap. Calculate monthly payment with the 15% factor, then track the 25-year target and compare another plan only if eligible.</p><p><strong>Debrief.</strong> $36,000 of discretionary income gives $450 before the cap under 15% IBR and $300 under 10%. The borrower’s cohort determines which calculation applies.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 24</div><h2>Repayment Assistance Plan mechanics</h2><p>Calculate RAP and explain its mechanics.</p><div class=\"callout\"><p>RAP charges a percentage of AGI by bracket and reduces the monthly payment by $50 per eligible claimed dependent, with a $10 floor.</p></div><ol class=\"steps\"><li>Confirm eligible debt</li><li>Use applicable AGI bracket</li><li>Subtract dependent credit</li><li>Apply the $10 floor</li></ol><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>RAP charges a percentage of AGI by bracket and reduces the monthly payment by $50 per eligible claimed dependent, with a $10 floor. Use the published bracket amount, not marginal tax bracket math. At AGI of $10,000 or less, the base is $10 monthly. Terms include 360 qualifying months and limited interest/principal protections for qualifying payments. Parent PLUS and consolidations containing it are excluded.</p><p>Confirm eligible Direct debt, select the rate using applicable AGI, divide by 12, subtract eligible dependent reductions and apply the floor. Model the balance with official rules for qualifying full and timely payments.</p><p><strong>Debrief.</strong> $85,000 at 8% with one eligible dependent gives $516.67 monthly. Log AGI, dependent source and bracket.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 25</div><h2>Tracking forgiveness credit under RAP and IBR</h2><p>Reconcile distinct IBR, RAP and PSLF targets.</p><div class=\"callout\"><p>Maintain separate IDR and PSLF counts per loan.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Maintain separate IDR and PSLF counts per loan. Review the destination plan’s rules about which prior months can count and how a new consolidation changes the clock. The final RISE rule allows qualifying IBR payments and qualifying PAYE payments made before July 1, 2028, to count toward RAP under the stated conditions. Review <a href=\"https://www.ecfr.gov/current/title-34/subtitle-B/chapter-VI/part-685/subpart-B/section-685.209\">34 CFR 685.209</a> for other periods and exceptions. Keeping a previously earned month and having the same number of months remaining are different questions when the target changes from 240 to 360.</p><p>Record the old count, destination plan, months accepted under its rule, target and months remaining. Verify which payment types transfer under the final rule and compare the date to possible future borrowing.</p><p><strong>Debrief.</strong> If 144 months were verified as transferable, a 240-month target leaves 96 and a 360-month target leaves 216. Validate the premise before putting either date into a memo.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 26</div><h2>Advanced IDR case analysis</h2><p>Stress-test eligibility and payments across a mixed loan file.</p><div class=\"callout\"><p>For mixed histories, map loan type, holder, borrower, cutoff dates, current plans, status and credits before selecting any strategy.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>For mixed histories, map loan type, holder, borrower, cutoff dates, current plans, status and credits before selecting any strategy. Run baseline, lower-income and higher-income projections. Flag cliff effects, the treatment of married borrowers, changes after recertification and exposure to discharge taxes.</p><p>Partition by holder, loan type, age and count. Create no-action, plan change, and eligible consolidation alternatives. Model low, base and high income and verify conditional approvals before taking irreversible action.</p><p><strong>Debrief.</strong> A borrower has older FFEL and newer Direct loans. Compare keeping loans separate with applicable federal consolidation. Identify access gained, legacy options lost and count impact.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 27</div><h2>The RISE repayment rules</h2><p>Use the final RISE rule to validate a plan change.</p><div class=\"callout\"><p>RISE is the Department of Education rulemaking implementing statutory changes.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>RISE is the Department of Education rulemaking implementing statutory changes. Separate statute, final regulation, effective date, agency implementation and individual servicer notice. Maintain a rule ledger with source, publication date, effective date and impacted borrower cohort. Review dated guidance before teaching a change.</p><p>Read the final regulation and effective-date provision. Compare agency materials to implementation and reconcile account evidence. Record the date on which the rule was checked.</p><p><strong>Debrief.</strong> A draft summary conflicts with final rule text. Use the final text and confirm effective timing and applicable borrower facts before relying on it.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 28</div><h2>Worked IBR and RAP household cases</h2><p>Explain the effect of changed dependents.</p><div class=\"callout\"><p>Case A claims two eligible RAP dependents and has $75,000 applicable AGI.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Case A claims two eligible RAP dependents and has $75,000 applicable AGI. RAP is $337.50. If a verified IBR poverty allowance is $36,000 and 10% applies, IBR is $325 before the cap. Case B has $44,000 applicable AGI and one eligible RAP dependent. At 4%, RAP is about $96.67. Recompute both for the correct filing and family inputs when facts change.</p><p>Run each household change through RAP and IBR separately. Verify filing and spouse inputs. Identify the date the changed facts are relevant to the borrower’s application and check what documentation is accepted.</p><p><strong>Debrief.</strong> In Case A, losing one RAP dependent adds $50 monthly if the floor does not bind. IBR must be recalculated using its own family-size rules.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 29</div><h2>Payment timing and forgiveness records</h2><p>Track payments that support forgiveness.</p><div class=\"callout\"><p>Track due date, full amount due, date posted, plan, employment and official count.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Track due date, full amount due, date posted, plan, employment and official count. RAP PSLF timing rules can be strict, particularly for borrowers with post-cutoff loans. Avoid treating any late, partial, extra or paused month as qualifying without checking the applicable rule. Reconcile autopay and bank records after a plan change.</p><p>Capture due date, effective paid date, total required, plan, status and qualifying employer month. Watch first bills following a switch and reconcile posted payments to account records before claiming credit.</p><p><strong>Debrief.</strong> A bank receipt predates the due date but the servicer posted later. Keep evidence, ask how the servicer applied the effective date, and request correction if warranted.</p></aside></article><article class=\"slide\"><div class=\"tag\">Section 2 review</div><h2>Practice and discussion</h2><ol><li>Calculate RAP at $82,000 AGI with two eligible dependents using 8%.</li><li>For the same loan, 215 months have been confirmed eligible for a 240-month plan and a 360-month plan. How many months remain under each?</li><li>List eligibility evidence you would want before submitting a PSLF buyback request with 118 certified payments.</li><li>A borrower has variable commissions. What two sensitivities would you show when comparing eligible RAP and IBR?</li></ol><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>$82,000 × 0.08 ÷ 12 − $100 = $446.67.</p><p>25 and 145 months respectively. The target and eligible count are separate inputs.</p><p>120 or more certified qualifying employment months, two candidate months of eligible pause during the certified employment on the current outstanding Direct loan, and confirmation that buying them would result in forgiveness.</p><p>Any defensible pair such as annual AGI growth or decline, household input changes, recertification timing, forgiveness target changes, balance and potential discharge tax.</p></aside></article>"}, {"id": "Section_3_Teaching_Deck", "title": "Section 3 teaching deck", "html": "<div class=\"slide-controls hide-print\"><button id=\"prev\" type=\"button\">Previous</button><button id=\"next\" type=\"button\">Next</button><span id=\"counter\" aria-live=\"polite\"></span><label><input type=\"checkbox\" id=\"toggle\"> Show speaker notes</label></div><article class=\"slide\"><div class=\"tag\">Section 3</div><h2>Tax and financial advising</h2><section class=\"figure\"><h3>Compare annual taxes and loan payments together</h3><div class=\"wide\"><table><thead><tr><th scope=\"col\">Example household cost</th><th scope=\"col\">Joint filing</th><th scope=\"col\">Separate filing</th></tr></thead><tbody><tr><td>Taxes</td><td>$20,400</td><td>$24,000</td></tr><tr><td>Student loan payments</td><td>$10,800</td><td>$6,360</td></tr><tr><td>Combined annual cost</td><td>$31,200</td><td>$30,360</td></tr></tbody></table></div><p>Under these inputs, separate filing reduces combined cost by $840 before other effects. Verify both tax estimates and the plan’s income inputs.</p></section><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Show the two filing scenarios. Ask the group to explain the result in annual household dollars. Role-play the handoff to the client’s tax or mortgage professional.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 30</div><h2>Student loan case intake</h2><p>Convert a Valtoris Student Loan Report Card into verified intake.</p><div class=\"callout\"><p>Open with the borrower’s goal, deadline and immediate risk.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Open with the borrower’s goal, deadline and immediate risk. The Valtoris Student Loan Report Card is a starting point. Verify its inputs against account evidence. Gather consent, household and employment facts, plan and notice history, loan statuses, estimated budget and referral needs. Enter confirmed and missing information separately in TAC.</p><p>Document the client’s objective and deadline first. Compare self-reported data to statements, obtain consent, and name each outstanding item in TAC. Triage collection, imminent billing and school deadlines.</p><p><strong>Debrief.</strong> A client wants the lowest payment and has a collections notice. Triage the notice first, record its date and route questions about legal rights or response deadlines to qualified counsel.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 31</div><h2>Managing and documenting cases</h2><p>Manage milestones from application through confirmed billing.</p><div class=\"callout\"><p>Move from intake through verification, modeling, review, borrower decision and follow-up.</p></div><ol class=\"steps\"><li>Intake</li><li>Verify</li><li>Compare</li><li>Borrower submits</li><li>Confirm plan and bill</li></ol><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Move from intake through verification, modeling, review, borrower decision and follow-up. Document at least two viable paths when available. Name who will act, when and what will confirm completion. Explain that official forms are free. Borrowers control login, consent and submission. Have compliance review client-facing fees and marketing, including federal restrictions on advance fees for covered telemarketed debt relief.</p><p>For each action assign a person, due date and proof. Separate submitted, approved and in effect. Use supervisor review for sensitive choices and document an approved fee or scope only after compliance review.</p><p><strong>Debrief.</strong> An IDR submission receipt arrives. Keep the case open until the borrower verifies processing, the new plan and first bill, or the planned follow-up confirms a delay.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 32</div><h2>Helping clients retrieve loan documents</h2><p>Help a client retrieve records without handling credentials.</p><div class=\"callout\"><p>Walk the borrower through StudentAid.gov and servicer navigation while they control the screen and credentials.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Walk the borrower through StudentAid.gov and servicer navigation while they control the screen and credentials. Request only what is needed. Use secure transfer and approved access controls. Collect evidence of program, dates and counts plus the current bill and notices. Store a secure reference in TAC when the underlying document contains sensitive details.</p><p>Ask the borrower to sign in privately and use authorized secure transfer with minimum needed fields. For a screen-share, pause during authentication. Route accidental credential exposure through the approved process and direct secure account recovery.</p><p><strong>Debrief.</strong> A borrower texts a password and verification code. Do not use them. Route the exposure through your incident process and guide the borrower to secure their account.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 33</div><h2>Understanding loan repayment assistance programs</h2><p>Evaluate loan repayment assistance as part of compensation.</p><div class=\"callout\"><p>Loan repayment assistance programs can provide money toward eligible debt under an employer, occupation, school or government program.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Loan repayment assistance programs can provide money toward eligible debt under an employer, occupation, school or government program. Compare qualifying loans, employment rules, award schedule, tax treatment and obligations. A promised award is different from an executed award agreement.</p><p>Check qualifying debt, payment beneficiary, installment timing, service obligations, tax handling and exit terms. Get the benefit in writing before including it in a budget.</p><p><strong>Debrief.</strong> An employer advertises up to $10,000. Confirm whether private debt qualifies and when benefits vest before counting that amount in a job comparison.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 34</div><h2>Employee benefits under Sections 125 and 127</h2><p>Distinguish Sections 125 and 127 when reviewing employee benefits.</p><div class=\"callout\"><p>Section 125 generally governs cafeteria plans that let eligible employees choose among cash and qualified benefits.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Section 125 generally governs cafeteria plans that let eligible employees choose among cash and qualified benefits. Section 127 governs qualifying employer educational assistance, including qualifying student loan payments under a written program. A cafeteria-plan label alone does not establish a tax exclusion for loan repayment.</p><p>Identify the benefit under the written employer plan. Ask payroll whether the borrower and expense qualify. Review tax handling with the tax advisor and ensure the assistance is applied correctly to eligible debt.</p><p><strong>Debrief.</strong> HR calls a loan payment pretax. Ask for the written benefit terms and payroll treatment, then coordinate verification with a tax professional.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 35</div><h2>Service based loan repayment programs</h2><p>Compare public service incentives and service-based repayment separately.</p><div class=\"callout\"><p>NHSC, state and other profession-specific programs can require a qualifying role, site, license and service period.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>NHSC, state and other profession-specific programs can require a qualifying role, site, license and service period. Verify the award year, restrictions, overlapping obligations and clawback terms. Determine PSLF eligibility separately. For NHSC, site approval is central and qualifying loan repayment funds are exempt from federal income and employment taxes.</p><p>Validate role, license, approved service location, award year, eligible debt, duration, exit liability and tax impact. Model awarded funds alongside PSLF only after matching independent employer and payment rules.</p><p><strong>Debrief.</strong> A clinician has a potential NHSC site and 72 PSLF months. Verify the actual employer for PSLF and obtain the award terms before modeling service, award application and payoff together.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 36</div><h2>Business owners and student loans Part 1 Income inputs</h2><p>Build a bridge from business revenue to repayment income.</p><div class=\"callout\"><p>Separate business revenue, expenses, net profit, salary, distributions and federal AGI.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Separate business revenue, expenses, net profit, salary, distributions and federal AGI. A bank deposit is not a tax return input by itself. Build a CPA-verified bridge from gross receipts to the borrower’s projected and filed AGI.</p><p>Use books and tax documentation to distinguish revenue and net profit, then map adjustments and household income. Mark projected and filed numbers separately. Ask a tax professional to confirm the borrower-level AGI input.</p><p><strong>Debrief.</strong> A sole proprietor reports $180,000 revenue and $80,000 expenses. $100,000 is a preliminary net profit figure. Confirm the return, applicable adjustments and household inputs before estimating IDR.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 37</div><h2>Business owners and student loans Part 2 Entity and benefits</h2><p>Identify income from both wages and pass-through activity.</p><div class=\"callout\"><p>Compare entity scenarios with a CPA.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Compare entity scenarios with a CPA. A change from sole proprietor to S corporation can affect wages, pass-through income, retirement and compliance costs. Owner draws or distributions alone can misrepresent total taxable income. Factor in liquidity and the cost of entity administration before drawing a conclusion.</p><p>Compare the tax return, W-2 and K-1 when applicable. Consider contributions, business reserves and the cost of changing entities. Keep the entity choice grounded in the whole household and business plan.</p><p><strong>Debrief.</strong> A shareholder takes a $60,000 salary plus a distribution. Request the W-2 and applicable Schedule K-1. Do not model IDR using salary alone.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 38</div><h2>Business owners and student loans Part 3 Variable income</h2><p>Manage student loan payments with uneven business income.</p><div class=\"callout\"><p>Create low, base and high scenarios tied to plausible changes in business results.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Create low, base and high scenarios tied to plausible changes in business results. Record when a lower income can be documented for recalculation, when recertification occurs and what reserves can absorb a higher bill. Coordinate quarterly taxes and retirement contribution decisions with the appropriate professionals.</p><p>Build low, base and high AGI projections, use approved documentation for changes, and set recertification reminders. Put the projected payment range in the cash forecast. Coordinate tax reserves and owner liquidity.</p><p><strong>Debrief.</strong> A $500 monthly increase under the high scenario requires $6,000 of annual cash flow. Put that assumption into the household budget and set a review trigger when income changes.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 39</div><h2>Verifying source quality</h2><p>Create a source trail another advisor can audit.</p><div class=\"callout\"><p>Start with the federal statute or final regulation for the rule, current FSA guidance for implementation and account documents for borrower status.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Start with the federal statute or final regulation for the rule, current FSA guidance for implementation and account documents for borrower status. Use the IRS for tax guidance and the applicable lender guide for mortgage treatment. Treat calculators as estimates and screenshots as dated evidence. Record any unresolved differences.</p><p>Capture rule link, date, applicable provision, client-specific evidence and an unresolved question list. Compare the highest-quality source for each fact. Save the version used to build the case model.</p><p><strong>Debrief.</strong> The borrower’s servicer email conflicts with an old webinar handout. Check the current federal rule and obtain clarification about the borrower’s account before recommending action.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 40</div><h2>Student debt in mortgage underwriting</h2><p>Coordinate student debt documentation with a mortgage lender.</p><div class=\"callout\"><p>The qualifying mortgage payment can differ from the borrower’s actual bill.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>The qualifying mortgage payment can differ from the borrower’s actual bill. Fannie Mae’s guide permits using a verified $0 IDR payment in specified circumstances. Its guidance for deferment and forbearance differs. FHA, VA and other products can have different rules. Confirm the exact product and documentation with the lender before changing repayment or refinancing.</p><p>Get the exact product and required documentation before changing plans. Distinguish actual bill, credit-report data and the amount underwriting uses. Model debt-to-income changes with the lender’s input, preserving federal protections where possible.</p><p><strong>Debrief.</strong> A lender uses $600 monthly for a student loan despite a $0 bill. Ask which rule and status were applied. Request written confirmation of acceptable documentation.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 41</div><h2>Tax tradeoffs in repayment planning</h2><p>Compare total household cost across filing choices.</p><div class=\"callout\"><p>Compare household taxes plus loan payments for each viable filing scenario.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Compare household taxes plus loan payments for each viable filing scenario. Consider changes to credits, deductions, state taxes, both spouses’ loan payments and the timing of the change. Separately model possible tax on a future discharge. Coordinate filing decisions with the tax professional.</p><p>Calculate annual tax difference and annual changes in loan payments for both spouses. Incorporate verified credit and deduction differences. Evaluate timing and long-term forgiveness effects separately.</p><p><strong>Debrief.</strong> Separate filing lowers combined payments by $310 monthly and increases annual taxes by $2,400. The illustrative annual improvement is $1,320 before other effects.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 42</div><h2>AGI and filing status calculations</h2><p>Use AGI for repayment and taxable income for brackets.</p><div class=\"callout\"><p>AGI and taxable income serve different purposes.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>AGI and taxable income serve different purposes. Determine which AGI and dependents apply to the plan, including any spouse inputs. Tax brackets apply marginally to taxable income. RAP generally applies the relevant rate to applicable AGI, then applies the monthly dependent reduction and floor.</p><p>Bring AGI from the applicable documented inputs. Work through marginal rates for tax estimates and the plan’s distinct payment formula for loans. Verify dependent assumptions and spouse interactions.</p><p><strong>Debrief.</strong> A borrower has $75,000 AGI, one eligible RAP dependent and $60,000 taxable income. RAP at 7% is $387.50 monthly using applicable AGI. Estimate taxes separately using filing status and taxable-income brackets.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 43</div><h2>Domicile, community property and Form 1098</h2><p>Address separate filing and community-property records.</p><div class=\"callout\"><p>For married borrowers domiciled in a community-property state, separately filed federal returns can allocate community income under state and federal rules.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>For married borrowers domiciled in a community-property state, separately filed federal returns can allocate community income under state and federal rules. Form 8958 reports allocations when applicable. Form 1098-E reports student loan interest, while Form 1098-T generally reports tuition information. Tax treatment and documentation for an IDR calculation require separate verification.</p><p>Confirm domicile and how the tax professional allocates community and separate income. Use Form 8958 when applicable. Check whether the repayment process accepts alternate documents, and distinguish 1098-E from 1098-T.</p><p><strong>Debrief.</strong> A Texas spouse earns $110,000 and the other $40,000. Do not assume the lower spouse’s separate federal AGI equals salary. Obtain the CPA’s figures and confirm the plan’s accepted supporting documents.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 44</div><h2>How student loan tax treatment changed</h2><p>Identify possible future tax when debt is discharged.</p><div class=\"callout\"><p>The temporary broad federal exclusion for many student loan discharges ran through 2025.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>The temporary broad federal exclusion for many student loan discharges ran through 2025. Starting in 2026, assume a potential federal tax cost unless the discharge qualifies for a specific exclusion. PSLF and certain programs, including qualifying disability and death discharges, have specific federal treatment. Review state rules, discharge date and any Forms 1099-C with a tax professional.</p><p>Record expected discharge year and program, determine potential federal and state exclusions, and get tax professional input. Use multiple incremental tax estimates and avoid treating a future balance as certain.</p><p><strong>Debrief.</strong> If $40,000 is taxable and an illustrative blended incremental rate is 22%, model $8,800. A qualified tax professional should verify the exclusion and actual incremental tax.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 45</div><h2>Recent tax law changes and Section 127</h2><p>Review changes to Section 127 and deductions before modeling AGI.</p><div class=\"callout\"><p>The 2025 law made qualifying employer student loan assistance under Section 127 permanent.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>The 2025 law made qualifying employer student loan assistance under Section 127 permanent. The 2026 federal exclusion generally covers up to $5,250 in combined qualifying educational assistance under a written program. Check later-year indexed amounts and plan terms. Screen tax changes individually and distinguish below-AGI deductions from adjustments that change AGI. The law’s qualified tips, qualified overtime, eligible vehicle loan interest and enhanced senior deductions are reported on Schedule 1-A and can reduce taxable income without reducing AGI used in an AGI-based loan estimate.</p><p>Verify written plan, qualifying loan, annual combined educational assistance, and payroll. Determine whether a claimed deduction is above or below AGI before altering an IDR estimate.</p><p><strong>Debrief.</strong> An employer pays $3,000 of qualifying tuition and $2,500 on qualifying loans in 2026. Compare the combined $5,500 with the $5,250 exclusion and confirm payroll treatment of the excess.</p></aside></article><article class=\"slide\"><div class=\"tag\">Section 3 review</div><h2>Practice and discussion</h2><ol><li>A household saves $4,800 annually on student loan payments by filing separately, but owes $5,100 more in tax. What is the first-pass household effect?</li><li>Differentiate a $0 IDR payment from a forbearance in the lender conversation.</li><li>An employer pays $4,200 in tuition and $1,200 toward eligible loans under its written plan in 2026. How far over the general Section 127 cap is it?</li><li>Name three pieces of paper or approved records you would assemble for a business-owner IDR file.</li></ol><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>$300 higher annual direct cost under the assumptions.</p><p>Confirm the status with loan evidence and have the lender identify exact product rules. A verified $0 IDR payment may be treated differently from a temporary pause.</p><p>$5,400 total is $150 above the general $5,250 combined cap. Confirm payroll and eligibility.</p><p>Any relevant examples such as current filed federal return or approved income evidence, W-2 or K-1 where relevant, official loan records, current bill, or CPA documentation of household AGI projections.</p></aside></article>"}, {"id": "Section_4_Teaching_Deck", "title": "Section 4 teaching deck", "html": "<div class=\"slide-controls hide-print\"><button id=\"prev\" type=\"button\">Previous</button><button id=\"next\" type=\"button\">Next</button><span id=\"counter\" aria-live=\"polite\"></span><label><input type=\"checkbox\" id=\"toggle\"> Show speaker notes</label></div><article class=\"slide\"><div class=\"tag\">Section 4</div><h2>The 2026–2028 transition</h2><section class=\"figure\"><h3>Three dates can govern one borrower decision</h3><div class=\"wide\"><table><thead><tr><th scope=\"col\">Event</th><th scope=\"col\">What to verify</th></tr></thead><tbody><tr><td>SAVE notice deadline</td><td>Borrower’s dated notice, application status and fallback bill</td></tr><tr><td>July 1, 2026 eligibility cutoff</td><td>First disbursements, including any consolidation</td></tr><tr><td>By July 1, 2028 legacy sunset</td><td>Successor plan and legacy Parent PLUS timing, where applicable</td></tr></tbody></table></div></section><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Have learners identify the borrower’s deadline, the disbursement cutoff and the legacy-plan retirement date. Ask which verification step is urgent in the scenario.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 46</div><h2>Why legacy income driven plans still matter</h2><p>Identify when a legacy plan can still help.</p><div class=\"callout\"><p>Eligible pre-cutoff borrowers may still have IBR, PAYE or ICR options based on loan history.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Eligible pre-cutoff borrowers may still have IBR, PAYE or ICR options based on loan history. A legacy plan can be attractive for monthly cash flow or forgiveness horizon, even if it will phase out. Include a dated successor plan before recommending a transition-period option.</p><p>Audit current eligibility, recent first disbursements and the projected transition date. Compare the near-term payment and time to qualifying discharge. Record a fallback if income or loan status changes.</p><p><strong>Debrief.</strong> A pre-cutoff borrower expects PSLF in 11 months. Compare current qualifying plan continuity and the actual retirement timeline before changing plans.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 47</div><h2>Mapping options after REPAYE and SAVE</h2><p>Build a borrower-specific action plan after SAVE.</p><div class=\"callout\"><p>SAVE ended in March 2026.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>SAVE ended in March 2026. Verify the actual servicer notice for timing and pending application status. Build a list of currently eligible plans. Review whether paused months qualify, whether earlier plan status is restored after a pending application, and how the first bill will be set.</p><p>Find the notice, response deadline and current plan or pending application. Compare eligible options, select a confirmed action date, then watch the approval and first bill. Check the effect of forbearance months on count.</p><p><strong>Debrief.</strong> A borrower has 12 days to act. Confirm the notice deadline and eligibility today, then check that the request was received and the new bill matches the approved plan.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 48</div><h2>PAYE eligibility and payment mechanics</h2><p>Estimate payment and eligibility for legacy PAYE.</p><div class=\"callout\"><p>For eligible legacy borrowers, PAYE generally uses 10% of discretionary income, limited by the applicable 10-year Standard payment, with a typical 20-year horizon.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>For eligible legacy borrowers, PAYE generally uses 10% of discretionary income, limited by the applicable 10-year Standard payment, with a typical 20-year horizon. Check its borrower-vintage requirements and current enrollment rules. Plan for retirement by July 1, 2028.</p><p>Verify cohort and loan vintage before running the 10% discretionary-income calculation and the Standard cap. Note the sunset and timed fallback. Review recent applications or disbursements.</p><p><strong>Debrief.</strong> $30,000 discretionary income produces $250 monthly before the cap. Verify whether the borrower’s history makes PAYE available and compare a successor plan.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 49</div><h2>PAYE exit and the path back</h2><p>Check reentry before leaving PAYE.</p><div class=\"callout\"><p>Before switching, verify current enrollment rules and whether a later return would remain possible.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Before switching, verify current enrollment rules and whether a later return would remain possible. New disbursements or consolidation after the cutoff can close access to legacy plans. PAYE retirement also ends access. Keep written evidence of the rule and the client’s decision. Separate theoretical availability from eligibility for this file on the expected date.</p><p>Write down the proposed exit date, any planned new disbursement, the final transition deadline and the rules for returning. Run a scenario with the alternative plan as permanent if reentry is uncertain.</p><p><strong>Debrief.</strong> A borrower wants to switch temporarily and then return to PAYE. Model the fallback assuming return is unavailable, and verify current access before any submission.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 50</div><h2>Calculating ICR</h2><p>Calculate the ICR payment using both methods.</p><div class=\"callout\"><p>ICR generally uses the lesser of 20% of discretionary income or a 12-year fixed repayment amount adjusted for income.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>ICR generally uses the lesser of 20% of discretionary income or a 12-year fixed repayment amount adjusted for income. It generally has a 25-year term. Its discretionary-income measure differs from IBR. Use the published adjustment calculation or official estimate and verify date and loan eligibility.</p><p>Use the correct ICR discretionary-income inputs and the published income-adjusted 12-year amount. Compare both estimates and select the lower. Exercise assumes eligibility under current rules.</p><p><strong>Debrief.</strong> If the two verified ICR calculations are $400 and $310, the modeled payment is $310. Confirm the transition timing before treating it as long term.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 51</div><h2>ICR transition and Parent PLUS history</h2><p>Check the legacy Parent PLUS pathway before any new consolidation.</p><div class=\"callout\"><p>Parent PLUS is generally excluded from IDR without a qualifying legacy consolidation.</p></div><ol class=\"steps\"><li>Trace Parent PLUS lineage</li><li>Verify pre-cutoff consolidation</li><li>Verify ICR payment and window</li><li>Confirm IBR and PSLF separately</li></ol><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Parent PLUS is generally excluded from IDR without a qualifying legacy consolidation. Eligible Parent PLUS borrowers who consolidated before July 1, 2026, may be able to use ICR and, after at least one qualifying ICR payment in the July 4, 2025 to July 1, 2028 window under current instructions, request IBR. A consolidation containing Parent PLUS after the cutoff is generally outside IDR. The parent’s own employer and history determine any PSLF analysis.</p><p>Verify parent ownership, Direct Consolidation first disbursement by June 30, 2026, and documented ICR payment history. Check FSA’s specified payment window and options for IBR. Confirm limits before mixing parent and student debt.</p><p><strong>Debrief.</strong> A May 2026 consolidation has one posted ICR payment. Verify lineage and IBR access. Reassess the entire file before changing the plan or consolidating again.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 52</div><h2>Keeping PSLF on track through a plan change</h2><p>Keep a PSLF case moving during a plan transition.</p><div class=\"callout\"><p>Confirm qualifying employment, signed forms, loan type, accepted counts and qualifying plan.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Confirm qualifying employment, signed forms, loan type, accepted counts and qualifying plan. Track any month between the last old-plan bill and first new-plan bill. Tiered Standard does not qualify. Review case-specific RAP timing and payment rules and the status of any periods of pause.</p><p>Check employer eligibility, certified counts and bill dates. Monitor intervening account status and reconcile count after the switch. Model why a low fixed payment could still cost the borrower if it stalls progress.</p><p><strong>Debrief.</strong> An eligible borrower is seven qualifying months from PSLF and has a pending plan change. Capture official counts and dates, verify treatment of intervening months and track new bills.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 53</div><h2>Comparing transition plans</h2><p>Choose among repayment options using a decision record.</p><div class=\"callout\"><p>Create a matrix with available plan, estimated current payment, deadline, forgiveness count treatment, successor plan and trade-offs.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Create a matrix with available plan, estimated current payment, deadline, forgiveness count treatment, successor plan and trade-offs. Run both the near-term cash-flow impact and the longer forecast. For an eligible borrower, PAYE or ICR may bridge a period, RAP may offer balance protections, IBR may preserve legacy options, and a fixed plan may provide a clear payoff term.</p><p>Compare available plans through the client’s deadline and across a longer horizon. Specify what changes when legacy plans end. Add cash cost, interest treatment, time remaining and tax assumptions with a dated successor plan.</p><p><strong>Debrief.</strong> If PAYE is $260 today and RAP $310, compare cost through the expected switch date and afterward. Verify whether a pending new disbursement changes the table.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 54</div><h2>Worked transition cases</h2><p>Apply transition rules to real-world client trade-offs.</p><div class=\"callout\"><p><strong>Nurse:</strong> 96 PSLF payments, $90,000 eligible Direct, $95,000 applicable AGI and two RAP dependents.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p><strong>Nurse:</strong> 96 PSLF payments, $90,000 eligible Direct, $95,000 applicable AGI and two RAP dependents. RAP at 9% is $612.50 before any spouse-debt adjustment. A flat payment over 24 qualifying months is $14,700. Model a job change separately.</p><p><strong>Parent:</strong> Legacy May 2026 consolidation includes Parent PLUS and has one ICR payment. Verify the legacy IBR path, deadline and official loan history.</p><p><strong>Returning student:</strong> Defaulted Direct loans and school starts in eight weeks. Compare rehabilitation and eligible consolidation, verify aid timing with school and holder, and account for credit impact.</p><p>Run a former SAVE nurse case, a legacy Parent PLUS case and a returning student in default. Each requires a different first document and decision deadline. Identify one constraint that could reverse each recommendation.</p><p><strong>Debrief.</strong> For each case name the next action, its owner, due date and the evidence required to proceed.</p></aside></article><article class=\"slide\"><div class=\"tag\">Module 55</div><h2>Borrower eligibility decision</h2><p>Build the final eligibility and action record.</p><div class=\"callout\"><p>Apply the gates in order: identity and ownership, programs and lineage, first disbursement and cutoff dates, loan status, borrower cohort, employment and counts, applicable income details, notices and deadlines.</p></div><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>Apply the gates in order: identity and ownership, programs and lineage, first disbursement and cutoff dates, loan status, borrower cohort, employment and counts, applicable income details, notices and deadlines. Determine viable plans or escalation. Confirm the borrower’s choice and verify subsequent billing and counts.</p><p>Start with ownership and lineage, then dates, status and any default. Proceed to income, family, employer, counted months and notices. Record eligible plans, evidence gaps and next owner. Confirm borrower submission and the later official result.</p><p><strong>Debrief.</strong> A client has a post-cutoff Direct loan, older FFEL and a spouse’s Parent PLUS. Split the file by borrower and loan group, inspect each for eligibility, and leave assumptions visible for supervisor review.</p></aside></article><article class=\"slide\"><div class=\"tag\">Section 4 review</div><h2>Practice and discussion</h2><ol><li>What three dates or date ranges should a former SAVE borrower with legacy loans check before choosing a plan?</li><li>A borrower’s Direct Consolidation including Parent PLUS was disbursed May 30, 2026. What qualifying event should be investigated before proposing IBR?</li><li>An approved ICR estimate compares $365 and $525 under the two methods. State the estimate and the plan timing caveat.</li><li>What three confirmations should an agent record after a borrower submits a plan selection?</li></ol><aside class=\"notes\" hidden><strong>Speaker notes</strong><p>The personal notice deadline, loan first disbursements including any new consolidation relative to July 1, 2026, and PAYE/ICR sunset or other legacy transition timing by July 1, 2028.</p><p>At least one eligible ICR payment in the specified FSA window and verification of the underlying history and current IBR rules.</p><p>$365. ICR is a legacy plan scheduled to end no later than July 1, 2028 and eligibility must be verified.</p><p>Submission receipt and date, approval or current plan status, and first bill amount and due date. Update forgiveness status if relevant.</p></aside></article>"}]','[{"prompt": "1. A client accepts a low initial payment but retires in five years. What do you line up?", "choices": ["Repayment start date against loan application date", "Only the next payment", "Later payments against retirement cash flow", "Only the original principal"]}, {"prompt": "2. Assuming the new $20,000 annual Parent PLUS cap applies, two parents each plan to borrow $12,000 for one child this year. How much does the aggregate request exceed that annual cap?", "choices": ["$4,000", "$12,000", "$2,000", "$0"]}, {"prompt": "3. Which record generally reports applicable married separate community-property allocations?", "choices": ["Form 8958", "Form 1098-T", "A servicer ACH receipt", "Form 1098-E"]}, {"prompt": "4. Which question should open a consult when default is reported?", "choices": ["Quote an upfront package immediately", "Promise rehabilitation will finish before aid", "Ask for the client’s password", "Ask for notices and verify deadline and holder"]}, {"prompt": "5. What should be recorded before relying on an approved pause?", "choices": ["Only the borrower’s chosen plan name", "Pause type, end date, interest and count treatment", "Just the initial approval timestamp", "Only the payment shown as zero"]}, {"prompt": "6. What can happen if the borrower misses the plan selection deadline?", "choices": ["Automatic PSLF discharge", "Automatic consolidation", "Automatic indefinite SAVE forbearance", "Applicable fixed plan placement"]}, {"prompt": "7. For a projected 2026 IDR discharge, which model is appropriate?", "choices": ["Assume all PSLF benefits are taxable", "Model potential tax and verify exclusions", "Assume all discharges remain tax free indefinitely", "Tax the entire original balance automatically"]}, {"prompt": "8. An eligible borrower’s income is expected to double in two years. What belongs in the repayment model?", "choices": ["Separate years with updated payment estimates and recertification timing", "Automatic forgiveness at the first recertification", "Zero interest without evidence", "One flat payment forever"]}, {"prompt": "9. ICR methods produce $475 and $390. Which amount is the modeled bill?", "choices": ["$390", "$865", "$432.50", "$475"]}, {"prompt": "10. Assume $28,000 discretionary income and no binding cap. What is legacy IBR per month?", "choices": ["$420", "$350", "$2,333.33", "$233.33"]}, {"prompt": "11. What should distinguish Report Card data from the completed inventory?", "choices": ["An assumption all statements match", "A promise that the grade is exact", "A higher self-reported total alone", "Source and verification status for each material fact"]}, {"prompt": "12. Why should a below-AGI deduction not be taken off AGI in an IDR model?", "choices": ["It raises AGI by the same amount", "It is a federal student loan credit", "It is always ineligible for tax purposes", "It reduces taxable income downstream of AGI"]}, {"prompt": "13. If 168 qualifying months are confirmed for a 360-month RAP target, how many remain?", "choices": ["168", "132", "72", "192"]}, {"prompt": "14. Which plan here is unsuitable for accumulating new PSLF credit?", "choices": ["Tiered Standard", "Eligible RAP", "Eligible IBR", "Eligible PAYE"]}, {"prompt": "15. How should a reviewer treat a gap between the borrower’s recollection and the official count?", "choices": ["Treat every paused month as qualifying", "Replace the count with the borrower estimate", "Audit and reconcile each disputed period", "Consolidate immediately to erase the discrepancy"]}, {"prompt": "16. An employer provides $2,800 in eligible tuition aid and $2,450 in qualifying student loan payments under its 2026 Section 127 program. How does that compare with the general exclusion limit?", "choices": ["$2,800 under", "$2,450 over", "Two separate $5,250 caps", "Exactly $5,250 combined"]}, {"prompt": "17. How should an agent confirm payroll treatment of a workplace education benefit?", "choices": ["Count assistance as PSLF automatically", "Request written program terms and verify with payroll and tax advisor", "Rely solely on the borrower’s loan statement", "Assume tax-free because HR used the word benefit"]}, {"prompt": "18. The export lists an old $18,000 loan now at zero, its $19,200 consolidation, and a $3,600 active loan. What goes in the active balance?", "choices": ["$40,800", "$19,200", "The active total is $22,800", "$21,600"]}, {"prompt": "19. A student’s offer includes a grant, work-study and an unsubsidized loan. What should happen before accepting the full loan?", "choices": ["Remove grant funds from the package", "Accept the entire loan by default", "Assume work-study is paid at disbursement", "Build a net-cost budget and confirm borrowing needed"]}, {"prompt": "20. An adjusted IDR count omits a specific quarter. What should the advisor assemble?", "choices": ["Month-specific status and supporting records", "A new FAFSA before checking records", "A letter promising correction", "A single undocumented total"]}, {"prompt": "21. The first payment is $240 and reaches $520. Which budget test matters?", "choices": ["Use the loan balance as monthly payment", "Test scheduled increases and available cash flow", "Assume graduation increases wages enough", "Model $240 forever"]}, {"prompt": "22. A 2024 statement says REPAYE or SAVE. Which fact should guide today’s plan decision?", "choices": ["The oldest statement label", "Any plan shown in an old brochure", "Current account status and eligibility", "The lowest payment ever billed"]}, {"prompt": "23. A proposed rule conflicts with a final regulation. Which governs your rule analysis?", "choices": ["The largest servicer’s marketing page", "The oldest handout", "The proposal if newer in a search result", "Applicable final regulation"]}, {"prompt": "24. A graduate with $92,000 already counted toward a $100,000 cap asks for $20,500. What is the upper bound before other requirements?", "choices": ["$12,500", "$20,500", "$28,500", "$8,000"]}, {"prompt": "25. When might Fannie Mae’s guide allow a $0 student loan payment in underwriting?", "choices": ["Whenever a borrower says no bill arrived", "When acceptable documentation verifies actual $0 IDR", "Whenever a loan is in forbearance", "For every mortgage program"]}, {"prompt": "26. A legacy IBR estimate is $475 before a verified cap of $425. What monthly amount should be modeled?", "choices": ["$50", "$900", "$475", "$425"]}, {"prompt": "27. What is the best evidence that a pause month counts toward PSLF?", "choices": ["A bank statement alone", "A calendar reminder", "Official status, count and qualifying employment evidence", "A zero bill alone"]}, {"prompt": "28. A borrower pays $200 extra intending to reduce one high-rate loan. What evidence confirms the result?", "choices": ["The spouse’s credit report", "The original note alone", "The bank withdrawal alone", "Loan-group posting history and allocation details"]}, {"prompt": "29. A Parent PLUS consolidation first disburses in August 2026. What is the general plan direction?", "choices": ["Use the child’s IBR cohort", "Apply the legacy ICR bridge automatically", "Check Tiered Standard. RAP excludes that consolidation.", "RAP is automatically available"]}, {"prompt": "30. Which input supports a $50 monthly RAP reduction?", "choices": ["Any supported adult", "Eligible claimed dependent", "A nondependent housemate", "The borrower’s employer"]}, {"prompt": "31. PAYE discretionary income is $42,000 with a $325 cap. What is the estimate?", "choices": ["$525", "$420", "$350", "$325"]}, {"prompt": "32. Two eligible plans have the same payment today. What can still change which one fits?", "choices": ["Only the plan abbreviation", "Verified forgiveness horizon, balance behavior and later income", "Only the original servicer brand", "Nothing if today’s payments match"]}, {"prompt": "33. What turns advertised loan assistance into a dependable planning input?", "choices": ["A recruiter’s verbal estimate", "Written terms, eligibility and timing", "The borrower’s debt balance", "A comparable employer’s benefit"]}, {"prompt": "34. Verified IBR costs $25 more monthly but may finish several years earlier. What is the next calculation?", "choices": ["Private refinance premium", "Only the $25 difference", "Only the original principal", "Total cash cost and verified remaining months"]}, {"prompt": "35. A calculator and account notice conflict on the actual deadline. Which should be investigated first?", "choices": ["The dated notice and official confirmation with the servicer", "An agent’s recalled date", "An unrelated borrower’s email", "The calculator’s generic date"]}, {"prompt": "36. A student’s FAFSA is processed but a loan is absent from the bill. Who verifies school certification and payout timing?", "choices": ["Mortgage lender", "Employer benefits team", "School financial aid office", "Private credit bureau"]}, {"prompt": "37. A service award lists a penalty if the borrower leaves early. How should it be modeled?", "choices": ["Deduct it from the balance before award", "Include the written exit consequences in the downside scenario", "Assume the penalty will be waived", "Ignore it if the role otherwise qualifies for PSLF"]}, {"prompt": "38. Which should be resolved before a joint household recommendation about the spouse’s Parent PLUS?", "choices": ["The best quoted private APR first", "Whether the spouses use the same email", "The child’s payment preference only", "Ownership, lineage, dates and status"]}, {"prompt": "39. Principal is $25,000, accrued interest is $1,500, and no capitalization occurred. What base is used for the next simple-interest estimate?", "choices": ["$23,500", "$26,500", "$25,000", "$1,500"]}, {"prompt": "40. Assuming 10% IBR, $0 discretionary income and ordinary formula eligibility, what does the formula produce?", "choices": ["$10 RAP minimum", "10% of the total balance", "$50 dependent reduction", "$0 before any case-specific check"]}, {"prompt": "41. A new undergraduate Direct Loan is first disbursed in September 2026. Which 2026–27 rate category applies?", "choices": ["5%", "8.07%", "9.07%", "6.52%"]}, {"prompt": "42. Which provision addresses qualifying employer student loan educational assistance?", "choices": ["The PSLF employer certification form", "Section 125 by itself", "Section 127", "Section 529 automatically"]}, {"prompt": "43. A borrower sends a one-time code during a call. What is the safe action?", "choices": ["Save the code to TAC", "Ask for a second code for verification", "Forward to another agent", "Use neither the code nor the password"]}, {"prompt": "44. Separate filing saves $200 monthly on loans and costs $3,000 more in annual tax. What is the first-pass annual result?", "choices": ["$2,400 higher household cost", "$600 lower household cost", "$600 higher household cost", "$5,400 lower household cost"]}, {"prompt": "45. The first bill after a plan switch differs from the earlier estimate. What should the advisor do?", "choices": ["Alter the bill in TAC", "Tell the borrower to ignore the bill", "Check approved plan, input data and due date with the servicer", "Assume the old figure remains binding"]}, {"prompt": "46. What is the main irreversible trade-off when refinancing Direct Loans into private debt?", "choices": ["The old rate remains permanently", "Federal forgiveness counts transfer to the private loan", "Federal protections on refinanced debt are lost", "The servicer must approve PSLF first"]}, {"prompt": "47. Assume AGI $62,000, allowance $32,000 and a verified $225 cap. What is the estimate?", "choices": ["$375", "$225", "$250", "$516.67"]}, {"prompt": "48. A nonprofit employee with 96 certified months moves to a nonqualifying job. What happens to the existing qualifying months?", "choices": ["Retained, with no new credit during nonqualifying work", "Transferred to the new employer’s private benefits", "All are erased", "All remaining months instantly qualify"]}, {"prompt": "49. A Direct loan has high qualifying credit and an FFEL loan has none for PSLF. What comes first?", "choices": ["Separate and verify both paths", "Pay off Direct immediately", "Average the counts by number of loans", "Transfer PSLF credit to the FFEL loan manually"]}, {"prompt": "50. Which record best establishes whether a legacy loan is FFEL?", "choices": ["Federal record and loan program", "Job title", "Only the lender logo", "Payment amount"]}, {"prompt": "51. Receipts are $140,000 and deductible business expenses are assumed at $52,000. What is preliminary net business profit?", "choices": ["$192,000", "$52,000", "$88,000", "$140,000"]}, {"prompt": "52. A lender classifies the loan as “forbearance” while the borrower calls it a $0 IDR bill. What first?", "choices": ["Use one generic DTI assumption", "Verify the actual loan status and acceptable documentation with the lender", "Demand that underwriting use zero for every product", "Change the loan immediately"]}, {"prompt": "53. Two loans have equal balances at 4% and 8%. What is their unrounded weighted rate?", "choices": ["4%", "6%", "8%", "12%"]}, {"prompt": "54. A federal payment posted to the wrong loan group. Who should receive the correction request first?", "choices": ["The school registrar", "The IRS", "The borrower’s employer", "The servicer"]}, {"prompt": "55. Who is the borrower on a Grad PLUS loan?", "choices": ["The school", "The employer", "The student’s parent", "The graduate or professional student who signed"]}, {"prompt": "56. A client has 117 payments and 119 certified employment months. Can they qualify for buyback today?", "choices": ["No, 120 certified employment months are required", "Yes, because 117 is above 100", "Yes, if private loans are added", "Yes, any missed months can be bought"]}, {"prompt": "57. Separate filing saves $180 monthly on loans and costs $1,900 more in tax. What is the annual difference?", "choices": ["$4,060 savings", "$260 savings", "$1,720 savings", "$260 extra cost"]}, {"prompt": "58. A borrower could achieve PSLF before PAYE ends. What must be validated before keeping PAYE?", "choices": ["Only the monthly bill", "The projected principal at age 65", "Eligibility, counts, employment and timing", "Whether a private lender offers a lower rate"]}, {"prompt": "59. A borrower wants to buy back months before the first disbursement of their current consolidation loan. What is the result on that current loan?", "choices": ["Only one month is excluded", "Those earlier months cannot be bought back on the new loan", "A private loan payment restores the months", "All months transfer automatically for buyback"]}, {"prompt": "60. Using 365 days, what is 30 days of simple interest on $36,500 at 6%?", "choices": ["$180", "$219", "$60", "$2,190"]}, {"prompt": "61. At $45,000 AGI and two eligible claimed dependents, using 4%, what is RAP?", "choices": ["$150", "$10", "$50", "$100"]}, {"prompt": "62. A business owner reports $95,000 net profit plus other taxable household income. Which is appropriate before quoting IDR?", "choices": ["Use the business’s checking balance", "Reconcile to the documented applicable AGI", "Exclude all nonbusiness income", "Use net profit as AGI automatically"]}, {"prompt": "63. A likely payment range is $320 to $720. What annual cash buffer covers the difference?", "choices": ["$8,640", "$3,840", "$400", "$4,800"]}, {"prompt": "64. Employer pays $4,000 tuition and $1,500 qualifying principal in 2026. Compare to the general $5,250 limit.", "choices": ["$250 over", "$1,500 over", "Within limit because the two amounts have separate caps", "$250 under"]}, {"prompt": "65. A borrower with defaulted Direct loans starts college in six weeks and wants the default off their credit. What should the advisor do?", "choices": ["Guarantee both outcomes within six weeks", "File for PSLF as the timing solution", "Compare rehabilitation and eligible consolidation, and verify timing with holder and school", "Ignore the school deadline because prior loans are federal"]}, {"prompt": "66. A borrower will accept a new federal loan next term. What should the written recommendation specify before a legacy plan switch?", "choices": ["That the borrower''s spouse sets loan eligibility", "That legacy access is locked forever", "That loan date affects only interest", "How the new first disbursement affects plan access and the fallback plan"]}, {"prompt": "67. Under the general Tiered Standard tiers, which term applies to exactly $100,000 of applicable principal?", "choices": ["25 years", "15 years", "10 years", "20 years"]}, {"prompt": "68. Which item is essential when a borrower considers Graduated repayment and has flat expected wages?", "choices": ["A schedule of increases and a cash-flow stress test", "A sponsor’s email", "An assumption all payments stay the same", "Only the first month’s payment"]}, {"prompt": "69. What event can remove eligibility for legacy plans when planning a return to PAYE?", "choices": ["An employer confirming work dates", "Updating a mailing address", "A new post-cutoff disbursement", "Downloading a new statement"]}, {"prompt": "70. An illustrative $25,000 taxable discharge faces an 18% effective incremental tax assumption. What is the reserve estimate?", "choices": ["$1,800", "$20,500", "$4,500", "$450"]}, {"prompt": "71. A RAP payment above the floor loses one eligible claimed dependent, with all other inputs unchanged. What is the typical change?", "choices": ["Always stays flat", "Increases $50", "Decreases $50", "Increases by one percentage point"]}, {"prompt": "72. A RAP borrower with post-cutoff debt pays only half the billed amount by the due date. What should the advisor assume for PSLF planning?", "choices": ["Count half a month", "Do not assume the month qualifies", "Replace employer certification with bank receipt", "Count a full month automatically"]}, {"prompt": "73. RAP’s calculated monthly amount after dependent reductions falls below $10. What amount applies under the general floor?", "choices": ["$0", "$50", "$10", "The negative calculated amount"]}, {"prompt": "74. The cheapest plan today sunsets before the goal. What should the recommendation show?", "choices": ["Successor plan and after-sunset cost", "A guaranteed future payment", "An assumption that the old plan continues", "Only the cheap initial payment"]}, {"prompt": "75. A paused former SAVE month is missing from the PSLF tracker. What is the best working assumption?", "choices": ["SAVE forbearance does not directly count. Check potential buyback separately if all criteria are met.", "The missing month proves a system error", "The borrower should submit a private payment", "It always counts automatically"]}, {"prompt": "76. An NHSC-approved site offers a contract. What still must be confirmed for PSLF?", "choices": ["Only the award size", "The patient’s federal program", "Actual employer and other PSLF requirements", "Only the NHSC site code"]}, {"prompt": "77. An S corporation owner asks you to estimate IDR using only payroll. What other information matters?", "choices": ["Pass-through and household income inputs", "Only a payroll stub", "Only the employer’s EIN", "Only distribution amounts"]}, {"prompt": "78. A $12,000 benefit vests over two years. The borrower may leave after six months. What term matters most for the estimate?", "choices": ["Vesting, payment dates and repayment obligation on departure", "Whether the employer is a household name", "The borrower’s mortgage term", "Only the advertised annual benefit"]}, {"prompt": "79. Holding rate and principal constant, what generally happens when a fixed term goes from 10 to 25 years?", "choices": ["Lower payment and higher lifetime interest", "Lower payment and equal total interest", "No change because rate is fixed", "Higher payment and lower lifetime interest"]}, {"prompt": "80. Which additional fact is central when checking eligibility for legacy Extended repayment?", "choices": ["Home equity", "Total private debt", "Applicable outstanding balance within the relevant program", "The borrower’s employer EIN"]}, {"prompt": "81. The low scenario is $275 monthly and the high scenario is $625. What is the monthly cash-flow spread?", "choices": ["$350", "$625", "$900", "$275"]}, {"prompt": "82. What record demonstrates a plan is active beyond the submission receipt?", "choices": ["A scheduler link", "A draft application", "The initial marketing email", "Approval and new plan or bill"]}, {"prompt": "83. Two private offers have the same starting payment. What improves the comparison?", "choices": ["Compare only lender names", "Assume the same starting payment means equal cost", "Compare only the loan balances", "Compare term, APR, reset rules and total cost"]}, {"prompt": "84. Which form generally reports student loan interest paid?", "choices": ["Form 1098-T", "Form 1098-E", "Form 1099-C", "Form 8958"]}, {"prompt": "85. What is the preferred TAC note for a sensitive tax document?", "choices": ["Credentials to retrieve it later", "A screenshot sent to a group chat", "Minimum needed facts and a permissioned reference", "A full unredacted tax return copied into notes"]}, {"prompt": "86. If $800 of interest capitalizes onto $10,000 at 5%, how much more annual simple interest is modeled at the new static principal?", "choices": ["$500", "$40", "$50", "$800"]}, {"prompt": "87. A borrower expects new federal borrowing in 2027. Which item should be included in today’s plan comparison?", "choices": ["An assumption PAYE stays open forever", "Only the new loan interest rate", "An assumption all old balances reset immediately", "A new-loan eligibility scenario"]}, {"prompt": "88. Which statement best explains the relationship between REPAYE and SAVE?", "choices": ["They are historical plan labels that need to be reconciled to current status and rules", "REPAYE guarantees current enrollment in SAVE", "They are both active for everyone", "They are private refinance products"]}, {"prompt": "89. How can a borrower carry the same verified eligible prior months into RAP but still face more months remaining?", "choices": ["PSLF sets the same target for every IDR plan", "RAP’s target can be longer", "Eligible months are always lost automatically", "The new target is based only on current interest"]}, {"prompt": "90. During a marketing call, a prospect offers to pay upfront for potentially covered debt relief. What is the appropriate agency action?", "choices": ["Collect half to reserve a date", "Assume any signed agreement permits it", "Collect it as a document charge", "Pause and route the fee and offer to compliance"]}, {"prompt": "91. A rule was published in May but a provision takes effect in July. Which date is used to determine applicability?", "choices": ["The day the borrower first heard about it", "The date of a search snippet", "The effective date of the applicable provision", "Always the publication date"]}, {"prompt": "92. RAP before the dependent reduction is $95. Three eligible dependents apply. What is the general monthly result?", "choices": ["$10", "$95", "$45", "$0"]}, {"prompt": "93. Before including Perkins in federal consolidation, what deserves review?", "choices": ["Whether a spouse has the same bank", "Any Perkins-specific cancellation benefit that may be lost", "The private rate on a different loan only", "The borrower’s age at graduation alone"]}, {"prompt": "94. Which income measure is generally used to start the RAP formula?", "choices": ["Mortgage debt-to-income percentage", "Applicable AGI", "Gross loan balance", "Taxable income after all deductions"]}, {"prompt": "95. Who confirms aid disbursement timing after a default is resolved?", "choices": ["The borrower’s employer alone", "The mortgage underwriter alone", "The school financial aid office, coordinated with the holder’s status evidence", "The tax preparer alone"]}, {"prompt": "96. On a static $30,000 balance, what first-year interest change approximates a rise from 7% to 9%?", "choices": ["$210", "$600", "$2,700", "$60"]}, {"prompt": "97. An eligible consolidated Parent PLUS borrower wants legacy IBR. What evidence is central?", "choices": ["Pre-cutoff consolidation and qualifying ICR payment", "A later private refinance", "The child’s nonprofit employer", "A new RAP enrollment"]}, {"prompt": "98. What should the case memo cite for a borrower-specific transition deadline?", "choices": ["Borrower’s dated notice and official guidance", "A past webinar''s date", "A generic online deadline", "A national news headline"]}, {"prompt": "99. Under the general tiers, exactly $50,000 falls in which term?", "choices": ["15 years", "20 years", "25 years", "10 years"]}, {"prompt": "100. A new consolidation shows $29,600 and two paid-off loans list original amounts of $10,000 and $17,000. What should the advisor report as outstanding, assuming no other active balances?", "choices": ["$56,600", "$2,600", "$27,000", "$29,600"]}]','CAADBDBAABDDDACDBCDABCDDBDCDCBDBBDACBDCDDCDCCCBAAACBBDDABCBACBDACDAACCBBCAACAAACADDBCBDABDCABBCBAABD');

